insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('portfolio', 'beginner', 'module', 'm01-capital-is-a-constraint', 1, 'OKONO''s gas compression project OK-2 is funded at a limit of 300.0000 million USD, left out at 450.0000 and funded again at 600.0000. What does that pattern say about how the engine chooses?', '["The engine ranks projects by risked EMV per million USD, and OK-2''s place in that ranking moves because the limit changes the ratio it is scored on.", "OK-2 was dropped at 450.0000 because the simulated loss probability of a set holding it crossed a ceiling the optimizer enforces on every run.", "Each limit is solved on its own for the combination of whole projects with the largest summed risked EMV, so a project has no fixed place in a queue.", "The run at 450.0000 fell back to a coarse grid that could not fit a capex of 180.0000, while the runs at the other two limits used the exact grid."]'::jsonb, 2, 'OK-2''s ratio of risked EMV to capex is the same at every limit; what changes is what else the money buys, so at 450.0000 OK-1 + OK-3 + OK-4 returns 291.0000 without it.'),
  ('portfolio', 'beginner', 'module', 'm01-capital-is-a-constraint', 2, 'OK-3 carries npv_p10 700.0000 and npv_p90 210.0000 beside its npv_p50 of 420.0000. What part do the two percentiles play in its risked EMV of 41.2500?', '["None: they set the success spread of 191.1747, which the engine uses only when it describes the risk of a funded set.", "They replace npv_p50 when both are entered, since the engine takes the middle of the entered range as the success case before weighting it by pos.", "They bound the success branch, holding pos x npv_p50 inside the entered range before the fail cost is taken off.", "They scale the fail cost, since the engine reads the gap between them as the size of the loss on a dry well."]'::jsonb, 0, 'Risked EMV is pos x npv_p50 - (1 - pos) x fail_cost, so 0.250000 x 420.0000 - 0.750000 x 85.0000 = 41.2500 with no percentile in it; the spread is (700.0000 - 210.0000) / 2.5631.'),
  ('portfolio', 'beginner', 'module', 'm01-capital-is-a-constraint', 3, 'The 450.0000 set carries a P(loss) of 0.123600 and the 600.0000 set a P(loss) of 0.001800. What part did those probabilities play in choosing each set?', '["They set a ceiling, so the optimizer rejected any set at 450.0000 whose simulated loss probability ran above 0.123600.", "They broke near ties, so of two sets within one grid cell of each other the one less likely to lose money won.", "They were weighted into the objective, so the exploration well entered the 450.0000 set only after a risk discount.", "None, because the optimizer maximises summed risked EMV alone and the risk summary is computed afterwards for the set it already chose."]'::jsonb, 3, 'The optimizer never sees a probability: it funds OK-1 + OK-3 + OK-4 for 291.0000 at 450.0000, and a lower risk set of nearly equal value is never offered.'),
  ('portfolio', 'beginner', 'module', 'm01-capital-is-a-constraint', 4, 'For the 450.0000 set the engine prints seed 20260829, iterations 10000, P(loss) 0.123600 and P90 -18.3574. Why does it show the seed?', '["Because the seed fixes the average correlation between projects, which is the one simulation input the risk summary has no other field to display.", "So anyone can rerun the same simulation and reproduce its loss probability and percentiles exactly.", "Because the loss probability is still read from a normal approximation, and the seed records which version of that approximation the run applied.", "Because the optimizer breaks ties with it, so another seed can fund another set."]'::jsonb, 1, 'The repaired engine simulates success, failure and the success NPV of each project in every one of 10000 iterations; before EC5-0 these figures came from a normal approximation with nothing to reproduce.'),
  ('portfolio', 'beginner', 'module', 'm01-capital-is-a-constraint', 5, 'For OKONO''s 450.0000 set the risk summary reports P90 -18.3574 and P10 738.1043, in million USD. What is -18.3574?', '["The 90th percentile of simulated portfolio NPV, the value nine draws in ten fall below, which means the set most likely loses money.", "The low case, the 10th percentile of simulated portfolio NPV under the exceedance convention.", "The amount by which the set''s capex could run over in a bad year, since a P90 on spending is the figure exceeded only one time in ten.", "The normal approximation''s low case, taken from an emv of 291.0000 and a stdDev of 271.6522, which the engine still prints beside the simulation."]'::jsonb, 1, 'P90 is the value nine outcomes in ten exceed, so it is the low case; the same set''s P(loss) of 0.123600 confirms most draws are positive, and the percentiles are read from the seeded simulation.'),
  ('portfolio', 'beginner', 'module', 'm01-capital-is-a-constraint', 6, 'An analyst types OKONO''s limit of 450.0000 million USD and every capex as counts of USD, keeping the NPVs in million USD. What in the output shows that anything changed?', '["A PortfolioInputError, since a limit above 5000 is outside the range the engine accepts and nothing is chosen.", "A unit warning, since the engine compares the limit with the NPVs and flags an inventory typed at the wrong scale.", "Nothing, since risked EMV per million USD is a ratio whose unit cancels out of every optimizer step.", "The resolution the engine reports, because the limit is now far above 5000 and the grid switches to the limit / 2000 per cell."]'::jsonb, 3, 'The exact grid of 1 million USD per cell needs whole numbers and a limit of at most 5000; the engine holds no currency or unit field, so the reported resolution is the only trace.'),
  ('portfolio', 'beginner', 'module', 'm01-capital-is-a-constraint', 7, 'One OKONO row has its capex typed in USD while its npv_p50 stays in million USD, beside five rows typed consistently. What does the engine do?', '["It optimises without an error, and the project, whose capex now looks a million times too large, simply never fits.", "It refuses the run with a PortfolioInputError, since a capex out of scale with its own NPV is caught by the same check that catches a negative capex.", "It rescales the row, reading the Suite''s million USD column label as a unit field to convert entries into.", "It funds the project at every limit, since so large a capex tops the ranking by risked EMV per million USD."]'::jsonb, 0, 'The only refusal is a negative capex; the engine adds whatever it is given, and a limit such as 1000.0000 cannot hold a capex typed a million times too large.'),
  ('portfolio', 'beginner', 'module', 'm01-capital-is-a-constraint', 8, 'The engine refuses an inventory with the message: Project "1" has a negative capex (-0.5); capex must be 0 or more. The project has no name and no id. Which row does a user counting rows from one have to fix?', '["The first row, since the engine numbers projects from one in its messages so that they match the row numbers the Suite shows beside the inventory.", "Every row whose capex is below 1, since the message reports the smallest capex found and the number in quotes counts how many rows offend.", "The second row, because with no name and no id the engine names the project by its position counted from 0.", "No row yet, since the check runs after a set is chosen and names a project dropped from it."]'::jsonb, 2, 'The message uses the name, then the id, then the position from 0, so "1" is the second project; the check runs before any set is chosen and no partial answer comes back.'),
  ('portfolio', 'beginner', 'module', 'm01-capital-is-a-constraint', 9, 'Before EC5-0 a capex of -150 was accepted without a word. Why does the repaired engine refuse it outright instead of clamping it?', '["A negative capex turns the risked EMV negative, and the engine refuses any project whose risked EMV is 0 or less rather than leaving it out.", "The knapsack grid cannot store a negative weight, so the refusal protects the array the optimizer builds and says nothing about what the input means.", "A clamp to 0 would charge the project a grid cell for nothing, and the engine refuses every input that would take capacity the project never asked for.", "A project that pays you to fund it breaks the idea of a limit."]'::jsonb, 3, 'Capex never enters the risked EMV line, and a project with EMV of 0 or less is excluded, not refused; the published message reads Project "B" has a negative capex (-150); capex must be 0 or more.'),
  ('portfolio', 'beginner', 'module', 'm01-capital-is-a-constraint', 10, 'A one in four exploration well has its chance of success typed as a percentage and its fail cost typed with a minus sign to show it is a loss. The run returns no error. How is the well valued?', '["As a certain success worth its whole npv_p50, since pos clamps to 1 and a negative fail cost is read as 0.", "As a certain failure, because a pos above 1 is out of range and the engine sets any out of range chance to 0 before it weights the two branches.", "At its intended risked EMV, because the engine divides a pos above 1 by 100 and the typed minus sign cancels the minus sign in the formula.", "It is never valued, since a pos outside 0 to 1 is refused with the same error as a negative capex."]'::jsonb, 0, 'The published posAboveOneClamps case returns 80.0000 for pos 1.4 on an npv_p50 of 80, and negativeFailCostIsZero returns 40.0000 for a fail cost of -30 at pos 0.5; neither sends an error or a note.'),
  ('portfolio', 'beginner', 'module', 'm01-capital-is-a-constraint', 11, 'Four inventories are run through the optimizer. Which one does the engine refuse outright?', '["One with a limit of 30.0000 that sits under every project, since no set can be built and the knapsack has nothing it can return.", "One holding a project whose npv_p10 is entered below its npv_p90, since a success spread cannot be built from an inverted range.", "One holding a project with a capex of -0.5.", "One holding a project with pos 1.4, since a chance of success above 1 lies outside the range the engine documents for pos."]'::jsonb, 2, 'The negative capex is the one refusal; limitBelowEveryProject at 30.0000 funds nothing with capex 0.0000, and a pos of 1.4 is clamped to 1 and returns 80.0000.'),
  ('portfolio', 'beginner', 'module', 'm01-capital-is-a-constraint', 12, 'The published gridOvershoot case funds a set whose capex lands over its limit on the coarse grid. What does the repaired engine do with it?', '["Refuses the run with a PortfolioInputError, since a funded capex above the limit breaks the one constraint the knapsack is built to hold.", "Returns the set and flags it, reporting overLimit true and overLimitBy 2.0000.", "Drops the last project it added and returns the smaller set, so that the funded capex always comes back inside the limit it was given.", "Reruns the whole inventory on the exact 1 million USD grid, which removes the overshoot and returns a set that spends no more than the limit."]'::jsonb, 1, 'A set over the limit is not refused, only flagged, and the overshoot here is 2.0000 million USD; the only refusal in the engine is a negative capex.'),
  ('portfolio', 'beginner', 'module', 'm01-capital-is-a-constraint', 13, 'A board asks what the runner-up set at OKONO''s 450.0000 limit was worth and why OK-2 dropped out. What can the engine''s output answer?', '["Neither question, since the output holds the funded set, its capex and its risked EMV and names no set that came close.", "Both, since the engine reports the ranked list by risked EMV per million USD beside the optimum, with 287.7500 as the best set it rejected.", "The runner-up''s value only, read as the gap between the set''s emv of 291.0000 and its P10 high case.", "The reason only, since each excluded project carries a note saying why it was left out."]'::jsonb, 0, 'The engine funds OK-1 + OK-3 + OK-4 for 291.0000 and says nothing about near misses; a ranked table giving 287.7500 is built by hand beside it.'),
  ('portfolio', 'beginner', 'module', 'm01-capital-is-a-constraint', 14, 'Sorting OKONO by risked EMV per million USD and funding down the list at 450.0000 gives OK-1 + OK-4 + OK-5 for 287.7500. Why does the engine reach 291.0000?', '["It ranks by plain risked EMV instead of the ratio, which puts the exploration well ahead of the workovers.", "It risks each project again in the simulation, which marks down the workovers'' certain success.", "It compares combinations of whole projects, while a list judges projects one at a time and stops when the next one does not fit.", "It uses a coarser grid than the hand list, and rounding lets the well''s capex fit beside OK-1 and OK-4."]'::jsonb, 2, 'OKONO''s limits are whole and under 5000, so the grid is exact at a resolution of 1.0000; the gain of 3.2500 comes from choosing the set, not from rounding or risk.'),
  ('portfolio', 'beginner', 'module', 'm01-capital-is-a-constraint', 15, 'A board paper labels OK-1''s capex of 120.0000 million USD with a P90. What is wrong with that label?', '["Nothing, as long as the label follows the exceedance convention, so that P90 names the capex figure the project exceeds nine times in ten.", "The label is reversed, since on a cost P10 is the low figure and P90 the high figure of spending.", "The label belongs to the set, so the paper should quote the 450.0000 set''s P90 instead.", "A capex is an amount chosen or estimated and never takes a P-label; the engine''s P90 is a portfolio NPV outcome, the low case."]'::jsonb, 3, 'P-labels sit only on a simulated portfolio NPV: for the 450.0000 set P90 is -18.3574, while a capex of 120.0000 or a limit of 450.0000 carries none.'),
  ('portfolio', 'beginner', 'module', 'm02-risking-a-project', 1, 'An analyst types OK-3''s npv_p50 as 41.2500, its already risked value, and keeps pos 0.250000 and fail_cost 85.0000 beside it. What happens to the well?', '["Nothing changes, because the engine notices a success case smaller than the weighted fail cost and reads the entry as a value already risked.", "It is risked twice, and the discounted row drops out of every budget it was funded in.", "The engine sets pos to 1 for that row, since a risked npv_p50 already carries its chance and the default is applied to the weight instead.", "It is funded more often, because a smaller npv_p50 narrows the success spread and the risk summary of any set holding it improves."]'::jsonb, 1, 'Weighted again by 0.250000 and still charged 0.750000 x 85.0000, the row goes below zero, and a risked EMV of 0 or less is never funded; the real 41.2500 comes from a success case of 420.0000.'),
  ('portfolio', 'beginner', 'module', 'm02-risking-a-project', 2, 'An exploration well is entered with an npv_p50 and a fail_cost, but the pos field is left out of the row entirely. How does the engine value it?', '["It refuses the row, since a project with no chance of success cannot be risked and the engine names the offending project in its error.", "At the middle of the range, since a missing chance of success is read as a coin toss until a value between 0 and 1 is entered.", "At its npv_p50 weighted by the average pos of the other projects, which is how the engine fills a chance nobody entered.", "As a certain success worth its npv_p50, since an absent pos defaults to 1."]'::jsonb, 3, 'The published unrisked case enters no pos and no fail_cost and returns 250.0000, its whole npv_p50 of 250, so a blank well is counted as if it cannot fail.'),
  ('portfolio', 'beginner', 'module', 'm02-risking-a-project', 3, 'OK-3''s loss of 85.0000 million USD is typed with a minus sign in front, because a loss feels negative. What risked EMV does the engine return?', '["The success branch alone, because a fail_cost below 0 is read as 0 and the dry hole becomes free.", "The same 41.2500, because the formula already subtracts the fail cost and the engine takes its absolute value before weighting it.", "More than the success branch, since minus a negative fail cost adds the loss back as a gain.", "No value, since fail_cost must be 0 or more and the engine refuses it like a negative capex."]'::jsonb, 0, 'The published negativeFailCostIsZero case, pos 0.5, npv_p50 80 and fail_cost -30, returns 40.0000, which is 0.5 x 80 with no failure branch and no warning.'),
  ('portfolio', 'beginner', 'module', 'm02-risking-a-project', 4, 'The published missingNpvIsZero case enters no npv_p50, a fail_cost of 8 and a pos of 0.25, and the engine returns -6.0000. What produced that number?', '["The fail cost weighted by pos, since a row with no success case is charged its loss at its chance of success instead of its chance of failure.", "A default of 1 for the missing npv_p50, applied the way a missing pos defaults to 1.", "The failure branch alone: a missing npv_p50 is 0, so 0.25 x 0 - (1 - 0.25) x 8 leaves only the loss.", "The capex of 10 weighted by the chance of failure, standing in for the loss."]'::jsonb, 2, 'Every unit of -6.0000 is the failure branch: (1 - 0.25) x 8. The engine never links fail_cost to capex and never refuses a row with no NPV.'),
  ('portfolio', 'beginner', 'module', 'm02-risking-a-project', 5, 'OK-3 has OKONO''s largest success-case NPV, 420.0000 million USD, yet its risked EMV of 41.2500 ranks fifth of six. What takes the value away?', '["Three chances in four of a dry hole losing 85.0000, a branch that removes more than half of what the one in four success adds.", "Its capex of 90.0000, which the engine subtracts from the success case before weighting what is left by the chance of success on the well.", "Its wide success spread of 191.1747, charged against the success case as a penalty for uncertainty.", "Its npv_p90 of 210.0000, which the engine uses as the success value when pos is below one half."]'::jsonb, 0, '0.250000 x 420.0000 - 0.750000 x 85.0000 = 41.2500, which is 0.098214 of the success case; capex and the percentiles never enter the line.'),
  ('portfolio', 'beginner', 'module', 'm02-risking-a-project', 6, 'At OKONO''s 450.0000 limit the funded set shows a total success NPV of 725.0000, and at 600.0000 one of 473.0000. Which reading is right?', '["The 450.0000 set is worth more, since success NPV counts every project at its npv_p50 and that is a set''s value.", "The 600.0000 set is worth more, 402.7500 of risked EMV against 291.0000; the larger success total comes from holding the exploration well.", "The optimizer maximises success NPV at 450.0000 and risked EMV at 600.0000, where the budget can carry risk.", "The two sets are worth the same, since success NPV and risked EMV converge once 10000 iterations are simulated."]'::jsonb, 1, 'Success NPV adds every best case as if all worked at once, and 725.0000 includes OK-3''s 420.0000 which happens one time in four; the optimizer maximises risked EMV only.'),
  ('portfolio', 'beginner', 'module', 'm02-risking-a-project', 7, 'The risk summary for OKONO''s 600.0000 set reads emv 402.7500 at a correlation of 0.000000. What does emv read at a correlation of 1.000000?', '["Less than 402.7500, since projects that fail together drag the expected value down as well as widening the range of outcomes.", "More than 402.7500, since projects that succeed together compound their success cases in the same draws of the simulation.", "A value that depends on the seed, since emv is read from the simulated draws.", "402.7500 again, since emv is the sum of the four risked EMVs and correlation changes only the spread."]'::jsonb, 3, '89.7500 + 115.0000 + 160.0000 + 38.0000 = 402.7500; emv comes in closed form, and correlation moves how far outcomes spread around that mean, never the mean.'),
  ('portfolio', 'beginner', 'module', 'm02-risking-a-project', 8, 'Two projects share capex, pos, npv_p50 and fail_cost, but one has an entered success range twice as wide as the other. How does the optimizer see them?', '["It prefers the narrower one, since the knapsack penalises spread and a riskier project needs more EMV.", "It prefers the wider one, since a wider range lifts npv_p10 and the engine averages it into the success case.", "As identical, since the success spread feeds only the risk summary and never the risked EMV the optimizer maximises.", "It cannot compare them until each has an npv_stddev, which the optimizer needs to rank projects."]'::jsonb, 2, 'The line is pos x npv_p50 - (1 - pos) x fail_cost; the spread, such as (200 - 50) / 2.5631 = 58.5229, is used only when the engine describes risk.'),
  ('portfolio', 'beginner', 'module', 'm02-risking-a-project', 9, 'What does OK-3''s risked EMV of 41.2500 million USD describe?', '["The most likely single result of drilling the well, since it lies between the success case and the loss.", "The NPV the well delivers in a typical case, its success case moved down by the chance of success.", "The median of the well''s simulated outcomes, read at seed 20260829 over 10000 iterations.", "An average over many such bets; in any one outcome the well succeeds around 420.0000 or fails and loses 85.0000."]'::jsonb, 3, 'No single outcome is 41.2500, and with a pos of 0.250000 the likeliest result is the loss; a set of a few risked projects can sit far from its EMV, as the 450.0000 set''s P(loss) of 0.123600 shows.'),
  ('portfolio', 'beginner', 'module', 'm02-risking-a-project', 10, 'A hand check writes OK-3''s value as pos x npv_p50 - fail_cost. What has it done wrong?', '["Nothing, since the engine also charges the whole fail cost and weights only the success case.", "Charged the full loss as if failure were certain, dropping the 0.750000 weight on the failure branch.", "Counted the capex twice, since a fail cost already includes the capital spent and subtracting it again takes the capex off a second time.", "Dropped the success weight, since the correct line multiplies the difference between npv_p50 and fail_cost by pos as a single term."]'::jsonb, 1, 'The hand line gives 20.0000, while 0.250000 x 420.0000 - 0.750000 x 85.0000 = 41.2500 is the engine value; a hand line that misses 41.2500 has dropped or doubled a weight.'),
  ('portfolio', 'beginner', 'module', 'm02-risking-a-project', 11, 'A project is entered with npv_p10 50 and npv_p90 200, the wrong way round, and no npv_stddev. What does the engine do with it?', '["Returns a success spread of 0.0000, silently removing the success range from the risk summary.", "Refuses the project, since an npv_p10 below npv_p90 breaks the exceedance convention.", "Swaps them, since (npv_p10 - npv_p90) / 2.5631 is taken as an absolute value and gives the same 58.5229 whichever way they are typed.", "Uses the negative spread, which widens the simulated range exactly as far as percentiles entered in the right order would have done."]'::jsonb, 0, 'The published invertedPercentiles case returns 0.0000 where the correct order gives 58.5229; there is no check that npv_p10 sits above npv_p90 and no message.'),
  ('portfolio', 'beginner', 'module', 'm02-risking-a-project', 12, 'The published zeroStddevFallsBack case enters npv_stddev 0 with npv_p10 200 and npv_p90 50, and the success spread comes back 58.5229. Why not 0?', '["The engine holds npv_stddev at a floor of 58.5229, so that no project is ever simulated with a success spread narrower than that.", "An entered standard deviation is always ignored when percentiles are present, which is why explicitStddev also returns 58.5229.", "Only a positive entered standard deviation wins; a zero falls back to (200 - 50) / 2.5631.", "A zero is read as missing, and a missing field takes the default of 1, which the engine then scales up by the percentile range."]'::jsonb, 2, 'explicitStddev, with npv_stddev 40, returns 40.0000, so an entered value does win when it is positive; 0 is passed over and the percentile fallback gives 58.5229.'),
  ('portfolio', 'beginner', 'module', 'm02-risking-a-project', 13, 'A risky project''s pos is mistyped as 1.4 and clamps to 1. Beyond its risked EMV, what else does the clamp change?', '["Nothing else, because the risk summary reads pos as typed and only the risked EMV line applies the clamp.", "The seeded risk summary draws it as a success in every iteration, so its funded set looks safer as well as more valuable.", "The seed, because the engine reseeds the simulation whenever a clamp fires, recording the correction.", "The grid, because a clamped row is charged an extra cell so the optimizer can mark it as corrected."]'::jsonb, 1, 'posAboveOneClamps returns 80.0000, a certain success, and at seed 20260829 over 10000 iterations such a project never contributes a failure to P(loss) or to the P90 low case.'),
  ('portfolio', 'beginner', 'module', 'm02-risking-a-project', 14, 'OK-3''s success spread is 191.1747 and its mixture standard deviation 238.6507, while OK-5 reads 12.8750 on both. Why do OK-5''s two figures agree?', '["The mixture also counts the drop from a success to a loss, and OK-5 cannot fail, so it has no such drop.", "OK-5''s percentiles are narrow, and the mixture scales the spread by the ratio of npv_p10 to npv_p90, which is close to one for the workovers.", "The mixture adds capex to the spread when pos is below 1, and OK-5''s pos of 1.000000 adds nothing.", "The mixture is simulated, and a certain success converges so fast that the two figures meet."]'::jsonb, 0, 'OK-3 drops from a success case of 420.0000 to a loss of 85.0000, which widens 191.1747 to 238.6507; OK-5 has pos 1.000000 and a fail cost of 0.0000.'),
  ('portfolio', 'beginner', 'module', 'm02-risking-a-project', 15, 'The published posBelowZeroClamps case enters pos -0.2 on npv_p50 80 and fail_cost 30, and returns -30.0000. What value of pos did the engine use?', '["-0.2 as typed, which makes the success branch negative and weights the failure branch by more than one.", "The default of 1, since a pos out of range is handled like a non-numeric one and replaced by the default.", "0.2, since the engine takes the absolute value of a negative chance before it weights the two branches.", "0, a certain failure worth minus its fail cost."]'::jsonb, 3, 'pos is held between 0 and 1, so -0.2 becomes 0 and the result is -(1 - 0) x 30 = -30.0000, the same as the posZero case; no warning says a clamp fired.'),
  ('portfolio', 'beginner', 'module', 'm03-choosing-under-a-budget', 1, 'At a limit of 750.0000 million USD the engine funds OK-1 + OK-2 + OK-3 + OK-4 + OK-5 for capex 690.0000. Why is the rest of the limit left unspent?', '["The optimizer holds back a reserve against the loss probability, sized from the simulated spread of the set it has just funded.", "OK-6''s risked EMV per million USD is the lowest left, and the optimizer stops at the first project whose ratio falls under its cut-off.", "The grid is coarse at that limit and rounds each capex up, so the five projects fill every cell although their capex sums to 690.0000.", "The only project left, OK-6, costs 310.0000, and the optimizer cannot fund part of a project."]'::jsonb, 3, '750.0000 - 690.0000 = 60.0000 is left, and OK-6 needs 310.0000; the limit is whole and under 5000, so the grid is exact and nothing was rounded.'),
  ('portfolio', 'beginner', 'module', 'm03-choosing-under-a-budget', 2, 'A spreadsheet takes OKONO''s 60.0000 left over at 750.0000, funds a matching slice of OK-6 with it, and reports a higher total than 444.0000. What is wrong?', '["Nothing, since the optimizer would reach that total on a finer grid and 444.0000 is a rounding.", "It describes a portfolio that cannot be built, since a slice of a tie-back delivers no share of its NPV.", "The slice should be priced at OK-6''s ratio of 0.464516, which the spreadsheet overstated.", "The slice leaves out OK-6''s fail cost of 120.0000, which has to be charged in full against any fraction of the project that is funded."]'::jsonb, 1, 'Projects are funded whole or not at all, so 444.0000 is the best buildable answer at 750.0000; OK-6 comes in only when the limit reaches 1000.0000.'),
  ('portfolio', 'beginner', 'module', 'm03-choosing-under-a-budget', 3, 'Walking OKONO''s ranking by risked EMV per million USD at a limit of 450.0000, funding each project that still fits, which project is the first to be skipped?', '["OK-5, whose ratio of 0.633333 falls below the cut-off once OK-4 is funded and more than half of the limit has been committed.", "OK-3, whose capex of 90.0000 is skipped straight after OK-1 because the exploration well ranks last on the ratio list.", "OK-2, which would take the running capex from 360.0000 to 540.0000.", "OK-4, whose capex of 240.0000 pushes the total past the limit once OK-1 and OK-2 have both been funded ahead of it."]'::jsonb, 2, 'The order is OK-1 at 0.747917, OK-4 at 0.666667, OK-2 at 0.638889 and OK-5 at 0.633333; OK-2 does not fit, OK-5 does, and the walk stops at capex 420.0000.'),
  ('portfolio', 'beginner', 'module', 'm03-choosing-under-a-budget', 4, 'The greedy set at 450.0000 is OK-1 + OK-4 + OK-5 for 287.7500, and the optimizer funds OK-1 + OK-3 + OK-4 for 291.0000. How does the project with the lowest ratio get into the best set?', '["It uses the 30.0000 the list left idle: 41.2500 on 90.0000 beats 38.0000 on 60.0000 once the whole limit counts.", "The optimizer ranks by plain risked EMV, where OK-3''s 41.2500 beats OK-5''s 38.0000.", "The optimizer credits the well with part of its success case of 420.0000, which the ratio leaves out.", "The optimizer lets the limit stretch by one grid cell, giving OK-3 room the ranked list lacked."]'::jsonb, 0, 'Swapping the workovers for the well spends the last 30.0000 and gains 3.2500; the grid is exact at 450.0000, so no stretch or rounding is involved.'),
  ('portfolio', 'beginner', 'module', 'm03-choosing-under-a-budget', 5, 'OKONO''s greedy set, OK-1 + OK-4 + OK-5 at capex 420.0000 and risked EMV 287.7500, loses to the optimizer at 450.0000. Is it a bad set?', '["Yes, since a set that leaves money unspent is always beaten by one that spends the whole limit.", "Yes, since a set built by walking a ranked list is never optimal and never on the frontier.", "No: it is the best set for 420.0000, a point on OKONO''s efficient frontier, and only not the best for 450.0000.", "No, since the two sets tie at 450.0000 once loss probability is weighed against the 3.2500 gap."]'::jsonb, 2, 'The frontier has a point at capex 420.0000 and risked EMV 287.7500; at 750.0000 the optimizer itself leaves 60.0000 unspent, so idle money alone does not mark a set as beaten.'),
  ('portfolio', 'beginner', 'module', 'm03-choosing-under-a-budget', 6, 'At OKONO''s 600.0000 limit the walk down the ratio ranking funds OK-1 + OK-2 + OK-4 + OK-5, the optimizer''s own set, for 402.7500. What does that agreement show?', '["That the ranking is optimal whenever the limit is over half of OKONO''s total capex of 1000.0000.", "That the 450.0000 result was a grid artefact, since the methods agree once rounding is avoided.", "That the optimizer itself walks the ratio ranking and departs only to break a tie between sets.", "Only that the ranking happened to fill this budget; nothing in it tells you in advance which budgets it will fill."]'::jsonb, 3, 'The walk runs 120.0000, 360.0000, 540.0000 and 600.0000 and fills the limit exactly, while at 450.0000 the same walk stops 3.2500 short; only solving the set tells the two apart.'),
  ('portfolio', 'beginner', 'module', 'm03-choosing-under-a-budget', 7, 'The published negativeEmvHugeBudget case has a limit of 10000.0000 and funds good + better for capex 120.0000 and risked EMV 75.0000. A third project, neg, would easily fit. Why is it left out?', '["The limit is above 5000, so the coarse grid charges neg more cells than its capex of 20.0000 and it can no longer fit beside the others.", "Its risked EMV is -44.0000, and funding it would lower the summed risked EMV by exactly that amount.", "It is refused as an input error, since a negative risked EMV breaks the knapsack.", "The optimizer only considers the projects the two largest risked EMVs need."]'::jsonb, 1, 'A risked EMV of 0 or less is never funded however much money is left, so 10000.0000 - 120.0000 stays unspent and the engine reports no error.'),
  ('portfolio', 'beginner', 'module', 'm03-choosing-under-a-budget', 8, 'In the published zeroEmvExcluded case a project with capex 30.0000 and risked EMV 0.0000 sits beside good at a limit of 500.0000. Why does the engine leave it out?', '["It adds nothing to the objective and still uses capex, so a risked EMV of 0 or less is never funded.", "Its capex of 30.0000 cannot fit beside good, since a limit of 500.0000 is checked on a grid of the limit / 2000 per cell.", "The engine rejects a zero risked EMV row as unfinished and returns an error naming it.", "It would be funded under a tight limit, since a zero project is dropped only when money is left over and idle capex costs nothing."]'::jsonb, 0, 'The engine funds good alone for capex 50.0000 and risked EMV 30.0000 with 450.0000 of the limit spare; 500.0000 is whole and under 5000, so the grid is exact.'),
  ('portfolio', 'beginner', 'module', 'm03-choosing-under-a-budget', 9, 'A licence commitment has a negative risked EMV but must be drilled. How is it handled with this optimizer?', '["Outside the optimizer, by taking its capex off the limit before the run, since no flag can force a project in.", "By marking it must-fund in the inventory, a flag the knapsack honours before it fills the rest of the limit with the best set.", "By typing its pos as 1, which funds it while the risk summary still draws its real failure chance.", "By raising the limit to 10000.0000, since a big enough budget forces every project in."]'::jsonb, 0, 'negativeEmvHugeBudget leaves its negative project out even at a limit of 10000.0000; a pos of 1 is used everywhere, so it would also hide the failure from the simulation.'),
  ('portfolio', 'beginner', 'module', 'm03-choosing-under-a-budget', 10, 'Where in the engine''s output does OKONO''s 60.0000 of unspent money at a limit of 750.0000 appear?', '["In the risk summary, as cash the simulation carries beside the funded set as a project that can neither succeed nor fail.", "In the funded set, as a placeholder project the optimizer adds so that the total capex it reports always equals the limit.", "Nowhere; it is derived by subtracting the funded capex of 690.0000 from the limit.", "In an unspent field beside the total capex, which the engine fills in whenever the funded set stops short of the limit."]'::jsonb, 2, 'The engine returns the limit, the funded set, its capex and its risked EMV of 444.0000; every unspent figure, including 60.0000, is worked out by hand.'),
  ('portfolio', 'beginner', 'module', 'm03-choosing-under-a-budget', 11, 'OKONO''s greedy walk leaves 30.0000 idle at 450.0000, and the optimizer leaves 60.0000 idle at 750.0000. Which idle money signals that a better set existed?', '["Only the 60.0000, since it is the larger share of its limit and the optimizer should have topped the set up.", "Both, since any capital left unspent is value given up and a set that spends more always exists.", "Neither, since the engine carries no time value, so idle money costs nothing at either limit.", "Only the 30.0000, since OK-1 + OK-3 + OK-4 spends all of 450.0000 for 291.0000, while no set at 750.0000 beats 444.0000."]'::jsonb, 3, 'At 450.0000 the idle 30.0000 cost 3.2500 of risked EMV; at 750.0000 OK-6 needs 310.0000, so 444.0000 is the best whole project answer.'),
  ('portfolio', 'beginner', 'module', 'm03-choosing-under-a-budget', 12, 'In the published tieIdenticalProjects case, twinA and twinB each cost 100.0000 and return a risked EMV of 50.0000 at a limit of 100.0000. The engine funds twinA. Why twinA?', '["Its name sorts first, since the engine sorts projects alphabetically before solving.", "It was built first, and the knapsack replaces a set only with one of strictly larger risked EMV.", "The seed 20260829 decided it, since the engine separates tied sets with a random draw so that repeated runs of the inventory agree.", "Its simulated P(loss) came out lower, since the risk summary is run on both tied sets and breaks the tie in favour of the safer one."]'::jsonb, 1, 'The golden accepts twinA or twinB at 50.0000; the choice follows the order the projects were entered, and re-sorting the inventory can change it.'),
  ('portfolio', 'beginner', 'module', 'm03-choosing-under-a-budget', 13, 'In the published tieDifferentComposition case the engine funds A alone for 80.0000 at a limit of 100.0000, and the golden also accepts B + C at 80.0000. What does the engine''s output tell a reviewer about B + C?', '["That it is worse, since the engine returns the unique best set and B + C must have fallen short of 80.0000 once placed on the grid.", "That it carries more risk, since the optimizer prefers a single project only after comparing the simulated spreads of the two sets.", "That it was found and flagged, since the engine lists every tied set beside optimalProjects whenever two sets reach the same value.", "Nothing: it has no field for alternative optima, and its risk summary is simulated for A alone."]'::jsonb, 3, 'B costs 40.0000 and C 60.0000, together 100.0000 for the same 80.0000; the tied set is never simulated, so a lower risk alternative stays invisible.'),
  ('portfolio', 'beginner', 'module', 'm03-choosing-under-a-budget', 14, 'At 450.0000 the optimizer''s set beats the greedy set by 3.2500. If a revision to one project''s inputs closed that gap to an exact tie, what would decide which set came back?', '["The loss probability, since a tie hands the choice to the risk summary and it favours the workovers'' certain success over the well.", "The larger total success NPV, used by the optimizer as a second key, favouring the well.", "The order the projects were entered in, since the first set built is kept against an equal one found later.", "The capex spent, since at equal value the knapsack prefers the set that leaves less unspent."]'::jsonb, 2, 'The optimizer compares risked EMV alone and keeps a set unless another is strictly larger, so a tie between the set at 450.0000 and the set at capex 420.0000 is settled by entry order.'),
  ('portfolio', 'beginner', 'module', 'm03-choosing-under-a-budget', 15, 'Raising OKONO''s limit from 450.0000 to 600.0000 adds 150.0000 of budget. What happens to the funded set?', '["It grows: OK-1 + OK-3 + OK-4 is kept and OK-2 is added on top, since a larger budget only ever buys projects in addition to the old set.", "It is rebuilt: OK-3 leaves, OK-2 and OK-5 come in, and OK-1 + OK-2 + OK-4 + OK-5 returns 402.7500.", "It grows: OK-5 and part of OK-2 are added, since the extra budget goes to the next projects down the list of risked EMV per million USD.", "It stays as approved at 450.0000 and leaves 150.0000 unspent."]'::jsonb, 1, 'Adding OK-2 to the 450.0000 set would overrun the limit of 600.0000 by 30.0000; the whole combination is solved again, and OK-3 is out at 600.0000.'),
  ('portfolio', 'beginner', 'module', 'm04-the-efficient-frontier', 1, 'On OKONO''s frontier point 3 sits at 120.0000 and 89.7500 and point 4 at 180.0000 and 127.7500. What is the best risked EMV a budget of 150.0000 million USD can buy?', '["A share of the 38.0000 that step 4 adds, priced at its 0.633333 per extra million USD over the 30.0000 above point 3.", "127.7500, since a frontier point is read as the value available to every budget from the point before it up to its own capex.", "89.7500, the value of the lower point, because no whole set of OKONO projects costing between those two capexes does better.", "The midpoint of the two values, since the frontier is a curve of best value and a budget halfway between two capexes earns halfway between their values."]'::jsonb, 2, 'The frontier keeps a point only where the best value rises, so 89.7500 holds for every budget from 120.0000 to just short of 180.0000. No project can be funded in part, so none of the 38.0000 is bought early.'),
  ('portfolio', 'beginner', 'module', 'm04-the-efficient-frontier', 2, 'Step 3 of the OKONO frontier reads 1.616667 per extra million USD. What does that ratio measure?', '["The trade of OK-3 for OK-1: 48.5000 of risked EMV gained for 30.0000 more capex.", "OK-1''s own return on capital, the risked EMV it earns for each million USD it costs, which is why it leads every ranking.", "The value of each single million from 90.0000 to 120.0000, any one of which could be spent to buy its share of the gain.", "The best project to add on top of point 2''s set, since a step reports the project a larger budget brings in."]'::jsonb, 0, 'Step 3 replaces OK-3 at 41.2500 with OK-1 at 89.7500. OK-1''s own ratio is 0.747917 per million USD of its capex, so the 1.616667 belongs to the swap and not to the project.'),
  ('portfolio', 'beginner', 'module', 'm04-the-efficient-frontier', 3, 'The OKONO frontier shows a step of 3.2500 three times, at points 2, 5 and 11. What is that step?', '["OK-3 added on top of the set before at a diluted ratio, since its 41.2500 is spread across the capex of the projects already funded.", "Rounding residue the grid leaves between whole cells, repeated wherever a capex does not divide evenly into the cell size.", "Three different small projects that each happen to be worth 3.2500 of risked EMV once their fail costs are charged.", "The same swap each time: OK-5 out and OK-3 in, a net 3.2500 for a net 30.0000 of capex."]'::jsonb, 3, 'OK-3 adds 41.2500 for 90.0000 and OK-5 takes away 38.0000 for 60.0000. On an exact grid of 1.0000 per cell there is no rounding to leave a residue.'),
  ('portfolio', 'beginner', 'module', 'm04-the-efficient-frontier', 4, 'A reader expects the step ratios on the OKONO frontier to fall as the budget grows, the way diminishing returns usually look. What does the frontier show?', '["They fall steadily once past point 3, where the best ratio anywhere on the frontier is reached and every later step is worth less.", "They need not fall: 0.108333 is followed by 1.616667, and 0.300000 by 1.191667, because each step is a change of whole sets.", "They fall on risked EMV but rise on success-case NPV, which is why the two curves cross close to the limit.", "They fall exactly as expected, and any rise is the grid''s rounding at the one million USD cell."]'::jsonb, 1, 'No project can be funded in part, so a step can swap a weak set for a strong one: step 7 buys 0.300000 and step 8 buys 1.191667 by trading OK-3 and OK-5 for OK-2.'),
  ('portfolio', 'beginner', 'module', 'm04-the-efficient-frontier', 5, 'With 450.0000 million USD to spend, a reader stops at frontier point 3 because its 1.616667 per extra million USD is the steepest step anywhere. What is the answer to the funding question?', '["89.7500 on OK-1 alone at 120.0000, since the best use of capital is the point that earns the most per extra million USD.", "291.0000 at the limit, on OK-1, OK-3 and OK-4; a steep step is a good trade at its budget and not a reason to stop spending.", "204.7500 at point 8, the last step whose ratio of 1.191667 stays above one, beyond which a million buys less than a million.", "287.7500 at point 10, since the final step''s 0.108333 per extra million USD is capital spent for almost nothing."]'::jsonb, 1, 'The question is what 450.0000 funds, and the frontier''s last point answers it: 120.0000 plus 90.0000 plus 240.0000 costs 450.0000 and returns 291.0000.'),
  ('portfolio', 'beginner', 'module', 'm04-the-efficient-frontier', 6, 'OKONO''s frontier point 10 sits at 420.0000 and 287.7500, one step short of the answer. Which set is behind it?', '["OK-1, OK-3 and OK-4 with 30.0000 left unspent, since the optimum''s projects are printed at a capex the grid rounded down.", "OK-1 and OK-4 plus a share of OK-3, the part of the exploration well that the 60.0000 left over could pay for.", "OK-2, OK-4 and OK-5, the set funded further along, printed at this point because the frontier lists sets in order of value.", "OK-1, OK-4 and OK-5, the set a greedy ranking by EMV per million USD produces."]'::jsonb, 3, '120.0000 plus 240.0000 plus 60.0000 is 420.0000 and 89.7500 plus 160.0000 plus 38.0000 is 287.7500. Greedy found a frontier point, and the last step swaps OK-5 for OK-3 for 3.2500 more.'),
  ('portfolio', 'beginner', 'module', 'm04-the-efficient-frontier', 7, 'The optimizer runs OKONO at a limit of 750.0000 million USD. Where does the frontier''s last point sit, and why?', '["At 690.0000 and 444.0000, with 60.0000 unspent, because no remaining project fits and OK-6 alone costs 310.0000.", "At 750.0000 and 444.0000, because the last point is always printed at the limit whatever its set costs.", "At 1000.0000 and 588.0000, the value of all six projects, since a limit is rounded up to the next whole set.", "At 690.0000 with a grid undershoot, the coarse rounding that leaves a set out, which a finer cell would recover."]'::jsonb, 0, 'A point is printed at what its set costs. OKONO solves on an exact grid of 1.0000 per cell, so the 60.0000 is genuine: OK-6 is the only project left and needs 310.0000.'),
  ('portfolio', 'beginner', 'module', 'm04-the-efficient-frontier', 8, 'The OKONO frontier ends at 450.0000 and 291.0000. What does it say about the chance that the funded set loses money?', '["That it is small, because a set on the efficient frontier is by definition the one with the least risk at its budget.", "That it is the lowest of any set at 450.0000, since the optimizer breaks ties between equal values toward the set with less spread.", "Nothing: it ranks on risked EMV alone, and the seeded Monte Carlo reports P(loss) 0.123600 for that set separately.", "That it matches the 600.0000 set''s, since both sit on one frontier and share every point up to 450.0000."]'::jsonb, 2, 'The last point is the best value, not the safest. At seed 20260829 and 10000 iterations the 450.0000 set shows P(loss) 0.123600 and the 600.0000 set 0.001800, and the frontier shows neither.'),
  ('portfolio', 'beginner', 'module', 'm04-the-efficient-frontier', 9, 'OKONO''s best value at a budget of exactly 450.0000 million USD is 291.0000. What does one more million buy?', '["0.733333, the ratio of the next step, which is the price at which each extra million converts into risked EMV.", "0.108333, the ratio of the step just taken, carried forward as the going rate for more capital.", "0.633333, OK-5''s own ratio, since OK-5 is the cheapest project and the one a small addition to budget funds first.", "0.0000: the value stays at 291.0000 until the budget reaches 480.0000, where it steps to 313.0000."]'::jsonb, 3, 'The 0.733333 is 22.0000 over 30.0000, an average across a whole step. No project can be funded in part, so every extra million inside a step buys 0.0000.'),
  ('portfolio', 'beginner', 'module', 'm04-the-efficient-frontier', 10, 'A 450.0000 million USD programme is offered 600.0000. What is the honest figure for what the extra budget is worth?', '["111.7500 of risked EMV for 150.0000 more capex, the difference between the two last points.", "The sum of the four step ratios between the two budgets, each one a price that the next million can be bought at.", "OK-2''s 115.0000, since the larger set is the smaller one plus OK-2.", "The last step''s 0.108333 per extra million USD, carried across the 150.0000."]'::jsonb, 0, '402.7500 at 600.0000 less 291.0000 at 450.0000 is 111.7500. The step just taken reads 0.108333, yet later steps buy 0.733333 and 1.191667, so the step behind never prices the steps ahead.'),
  ('portfolio', 'beginner', 'module', 'm04-the-efficient-frontier', 11, 'Step 12 of the OKONO frontier reads 0.733333, close to OK-1''s own 0.747917 per million USD. What does step 12 do to OK-1?', '["It brings OK-1 in, since a step whose ratio matches a project''s own ratio is that project being added on top of the set.", "It keeps OK-1 and adds OK-5 to the 450.0000 answer, which is the 30.0000 of capex the step reports.", "It drops OK-1, funding OK-2, OK-4 and OK-5 at 480.0000 for 313.0000.", "Nothing to OK-1, since step 12 only trades OK-3 for OK-5 and leaves the two projects that carry the set untouched."]'::jsonb, 2, '180.0000 plus 240.0000 plus 60.0000 is 480.0000 and 115.0000 plus 160.0000 plus 38.0000 is 313.0000. Step 12 drops both OK-1 and OK-3 from the 450.0000 answer, so the resemblance of the ratios is a coincidence.'),
  ('portfolio', 'beginner', 'module', 'm04-the-efficient-frontier', 12, 'A 600.0000 million USD OKONO programme is cut to 450.0000, and the planner drops OK-2 from the funded set because it frees 180.0000. What does that leave?', '["The solved answer, since smaller optimal sets nest inside larger ones.", "OK-1, OK-4 and OK-5 at 420.0000 for 287.7500, which is 3.2500 short of the solved answer.", "The best value the smaller budget can buy, since a project left outside the larger set cannot come back at a smaller budget.", "A set with 30.0000 held back to buy part of OK-3."]'::jsonb, 1, '402.7500 less 115.0000 is 287.7500. The optimizer reaches 291.0000 by bringing back OK-3, a project the 600.0000 set did not fund, so no single drop reaches the answer.'),
  ('portfolio', 'beginner', 'module', 'm04-the-efficient-frontier', 13, 'A programme funded at 450.0000 million USD is raised to 600.0000, and the planner keeps OK-1, OK-3 and OK-4 and adds whatever still fits. Where does building up stop?', '["At 329.0000 on 510.0000, after adding OK-5, since OK-2''s 180.0000 no longer fits; solving again reaches 402.7500.", "At 402.7500, since adding what fits to a solved set reproduces the solved set at the larger budget.", "At 402.7500 on 600.0000, after adding OK-2 and OK-5, the two projects the larger budget was always going to fund.", "At 313.0000 on 480.0000, the next frontier point, which is where a set built up from the smaller answer lands."]'::jsonb, 0, '291.0000 plus 38.0000 is 329.0000. The solved set at 600.0000 is OK-1, OK-2, OK-4 and OK-5, reached by giving up OK-3, so a funded set is a starting point for nothing.'),
  ('portfolio', 'beginner', 'module', 'm04-the-efficient-frontier', 14, 'The OKONO set funded at 600.0000 million USD sums to 473.0000 of success-case NPV, against 725.0000 for the set at 450.0000. Is the larger budget buying less value?', '["Yes, since success-case NPV is what the projects return when they work and the larger programme returns less of it.", "Yes, because the optimizer at 600.0000 fell back to a coarser grid and lost the exploration well to rounding.", "No, because success-case NPV is reported only for the smaller set and the 473.0000 is a partial total of the larger one.", "No: risked EMV rises from 291.0000 to 402.7500, and success-case NPV falls because OK-3''s 420.0000 success case leaves the set."]'::jsonb, 3, 'The optimizer maximises risked EMV, not success-case NPV. OK-3 is worth 420.0000 if it works and 41.2500 risked, so dropping it costs little value.'),
  ('portfolio', 'beginner', 'module', 'm04-the-efficient-frontier', 15, 'The frontier run to 600.0000 million USD and the frontier run to 450.0000 are compared point by point. What do points 0 to 11 show?', '["Higher values at the larger limit, because more projects become admissible and every budget has more sets to choose from.", "The same values up to point 10, then a lower point 11 on the larger run, since OK-3 is dropped from the set at 600.0000.", "The same capex and value at every point, ending both stretches at 450.0000 and 291.0000.", "Shifted capexes, since a longer run spreads its 2000 cells wider."]'::jsonb, 2, 'The best value at a budget does not depend on how far past it the frontier is run. What changes at 600.0000 is which set wins at the limit, OK-1, OK-2, OK-4 and OK-5 at 402.7500.'),
  ('portfolio', 'beginner', 'module', 'm05-the-grid-under-the-answer', 1, 'Every OKONO limit from 300.0000 to 1000.0000 million USD reports a resolution of 1.0000. Why is the 450.0000 answer free of rounding?', '["The money is entered in million USD, and any limit in million USD is solved on a grid of one million per cell.", "Every capex and the limit are whole numbers and the limit is at most 5000, so each project weighs exactly its capex in cells.", "overLimit reads false at every limit, and a false flag is the engine''s certificate that no rounding changed the set.", "The limit is under 2000, so the grid has more cells than million USD and rounds every capex finer than it is entered."]'::jsonb, 1, 'The exact grid needs whole numbers and a limit of at most 5000; OKONO''s capexes run from 60.0000 to 310.0000, all whole. The nonIntegerLimit case is in million USD too and still turns coarse at 0.225250.'),
  ('portfolio', 'beginner', 'module', 'm05-the-grid-under-the-answer', 2, 'The published nonIntegerLimit case enters its money in million USD with a limit of 450.5000. What grid does it solve on?', '["The exact grid at 1.0000 per cell, since every capex is whole and the limit is far under 5000.", "A coarse one at 225000.000000 per cell, since any limit that is not whole is converted to raw dollars before the cells are laid.", "The exact grid with one extra cell for the 0.5000 of headroom, which is how a fractional limit is honoured.", "A coarse one at 0.225250 per cell, because the limit is not a whole number."]'::jsonb, 3, 'The cell is 450.5000 over 2000, which is 0.225250 million USD. Typing a little headroom moves the whole solve off the exact grid without any change to the projects.'),
  ('portfolio', 'beginner', 'module', 'm05-the-grid-under-the-answer', 3, 'The published rawDollars case reports a resolution of 225000.000000. What is that number?', '["A capex cell in the money units entered, 450000000.0000 USD over 2000, because the limit is far over 5000.", "The precision of the answer''s value, meaning the risked EMV is reliable only to within 225000.000000 of the true optimum.", "A cell in million USD, since the engine always solves portfolio money in million USD whatever units were typed.", "The number of cells in the grid, which is why a raw-dollar inventory takes far longer to solve than one in million USD."]'::jsonb, 0, 'Resolution is capex per cell and not precision in value: 225000.000000 USD here and 0.225250 million USD in nonIntegerLimit. The grid holds 2000 cells whenever it turns coarse.'),
  ('portfolio', 'beginner', 'module', 'm05-the-grid-under-the-answer', 4, 'rawDollars and nonIntegerLimit both solve on a coarse grid and both land on A, B and D at 250.0000 with a golden gap of 0.0000. What should a reader take from that?', '["That a coarse grid is safe for these projects, since two matching answers show the rounding cancels out on this inventory.", "That the grid does not matter once the golden gap is 0.0000, so the resolution can be ignored on a user''s own inventory.", "A coarse grid can give the exact answer and is still unproven, so the funded capex must be checked against the limit in money.", "That both inventories are really the same exact problem, since the engine converts raw dollars to million USD before solving."]'::jsonb, 2, 'Once capexes are rounded to cells the knapsack solves a nearby problem. A user running their own inventory has no golden, so a gap of 0.0000 is never available to them.'),
  ('portfolio', 'beginner', 'module', 'm05-the-grid-under-the-answer', 5, 'In the published gridOvershoot case, A costs 4000.0000 and B 2002.0000 against a limit of 6000.0000 million USD at 3.000000 per cell. How do A and B fit on the grid?', '["B''s 2002.0000 does not divide evenly and rounds down to 667 cells, so A''s 1333 and B''s 667 fit inside the 2000.", "The limit is whole, so the grid is exact and A and B are simply charged their capex in one million USD cells.", "The engine tolerates a breach smaller than one cell, and 2.0000 is under the 3.000000 a cell holds.", "C''s 1995.0000 rounds up to fill the spare cells, which pushes the knapsack toward B as the better value per cell."]'::jsonb, 0, '2002.0000 over 3.000000 rounds to 667 cells, and 1333 plus 667 fills the 2000 exactly. In money the pair costs 6002.0000, 2.0000 over the limit.'),
  ('portfolio', 'beginner', 'module', 'm05-the-grid-under-the-answer', 6, 'gridOvershoot returns A and B at 800.0000 with overLimit true and overLimitBy 2.0000. What is the best value that truly fits the limit?', '["800.0000, since the flag records the breach and the set it flags is still the optimum the engine solved for.", "780.0000 on A and C, found by checking in money, since the engine does not re-solve when it detects the overshoot.", "800.0000 less a charge for the 2.0000 overshoot, since a flagged set is priced back inside the limit.", "B and C, the only pair that leaves the 4000.0000 project out and so cannot breach the limit."]'::jsonb, 1, 'C''s 1995.0000 keeps A inside 6000.0000, giving 500.0000 plus 280.0000, which is 780.0000. The golden gap of 20.0000 is the value the engine reached by breaking the limit.'),
  ('portfolio', 'beginner', 'module', 'm05-the-grid-under-the-answer', 7, 'What did the EC5-0 repair change in the gridOvershoot case?', '["It re-solves any overshooting set in money, so the case now returns A and C at 780.0000 with the flag kept for the record.", "It moved limits over 5000 onto the exact grid, which removes the rounding that let B squeeze into the cells.", "It refuses a set over the limit with an input error, the way a negative capex is refused, and funds nothing.", "It added the overLimit and overLimitBy flag; the grid still rounds and the set is still A and B at 800.0000."]'::jsonb, 3, 'Before EC5-0 a total capex of 6002.0000 sat beside a limit of 6000.0000 with nothing to mark it. The flag reports the overshoot of 2.0000 and does not correct it.'),
  ('portfolio', 'beginner', 'module', 'm05-the-grid-under-the-answer', 8, 'The golden gap on gridOvershoot is 20.0000, and on gridUndershoot it is -200.0000. Why are their signs opposite?', '["Positive gaps are the grid rounding value up and negative gaps the grid rounding value down, both at 3.000000 per cell.", "The sign follows overLimitBy, which is 2.0000 on one case and a negative shortfall on the other.", "One case solves on the exact grid and the other on a coarse one, and the exact grid always overstates the value.", "The gap is the engine''s EMV less the exact optimum: positive where the engine broke the limit, negative where it left value out."]'::jsonb, 3, '800.0000 less 780.0000 is 20.0000, and 660.0000 less 860.0000 is -200.0000. The positive gap is value the budget cannot pay for.'),
  ('portfolio', 'beginner', 'module', 'm05-the-grid-under-the-answer', 9, 'gridUndershoot funds X, Y and Z at 4500.0000 against a limit of 6000.0000 million USD, with overLimit false and overLimitBy 0.0000. What does the false flag establish?', '["That the grid did not change the answer, since the flag is raised whenever rounding moves the funded set in either direction.", "That the 1500.0000 unspent is genuine, because the engine checks every left-out project against the unrounded capexes.", "Only that the set is not over the limit; it cannot say a better set was squeezed out, and here W worth 200.0000 was.", "That the answer is the exact optimum, since EC5-0 repaired the undershoot along with the overshoot."]'::jsonb, 2, 'The flag watches the limit from one side only. The exact optimum funds all four at 860.0000, and finding D4 left this undershoot silent.'),
  ('portfolio', 'beginner', 'module', 'm05-the-grid-under-the-answer', 10, 'In gridUndershoot all four projects, W, X, Y and Z, fit inside 6000.0000 million USD in money. Why does the knapsack fund only three?', '["At 3.000000 per cell 1499.0000 and 1502.0000 both round up, to 500 and 501 cells, so the four weigh one cell more than the 2000 the limit holds.", "Z''s 1502.0000 pushes the money total of the four over 6000.0000, so one project has to leave the set, and the knapsack drops W because it is the least valuable of them.", "The knapsack keeps one project''s capex unspent on a coarse grid, as a reserve against rounding up.", "W''s EMV of 200.0000 falls below the value the grid assigns to a single cell at this resolution, so its value is rounded to nothing and it cannot win a place in the set."]'::jsonb, 0, 'Three weights of 500 and one of 501 exceed 2000 cells, so the knapsack drops W, the least valuable. The gap of -200.0000 is exactly W''s risked EMV.'),
  ('portfolio', 'beginner', 'module', 'm05-the-grid-under-the-answer', 11, 'Two answers leave money unspent: OKONO at 750.0000 leaves 60.0000, and gridUndershoot leaves 1500.0000. Which unspent money is genuine?', '["Both, because the optimizer never leaves money unspent unless no left-out project fits in the space.", "OKONO''s, because its grid is exact at 1.0000 and OK-6, the only project left, costs 310.0000; gridUndershoot''s hides W, which fits in money.", "gridUndershoot''s, since a coarse grid is solved in cells, and a count of whole cells cannot leave out a project whose capex still fits inside the limit.", "Neither, since unspent money on any grid means the knapsack stopped before it filled the limit."]'::jsonb, 1, 'On OKONO no remaining project fits in 60.0000. On gridUndershoot the 1500.0000 left over would pay for W at 1499.0000.'),
  ('portfolio', 'beginner', 'module', 'm05-the-grid-under-the-answer', 12, 'freeProjectTightLimit has a free project with capex 0.0000 and EMV 10.0000 beside A at capex 100.0000 and EMV 60.0000, at a limit of 100.0000. Why does the engine fund A alone?', '["A project with capex 0.0000 is treated as unentered and skipped, the same way a missing npv_p50 is read as zero.", "The free project''s EMV of 10.0000 is too small to beat A''s, and the optimizer funds the single best project at a tight limit.", "The grid weighs every project at max(1, round(capex / cell)), so the free project takes one cell and A already fills all 100.", "overLimit would read true if both were funded, so the engine drops the cheaper project to keep the flag false."]'::jsonb, 2, 'The golden optimum funds both for 70.0000, but on the grid they need one cell more than the limit holds. This is finding D2, which EC5-0 left as it was.'),
  ('portfolio', 'beginner', 'module', 'm05-the-grid-under-the-answer', 13, 'freeProjectSlack raises the limit to 101.0000 and the engine funds the free project and A at capex 100.0000 for 70.0000. What did the extra million buy?', '["The one cell the grid charges the free project; the million itself is never spent.", "A share of A''s capex overrun, since the engine lets a tight budget fund A only once it has a million of contingency.", "The free project''s 10.0000 at a price of one million USD, which is its true cost once its capex is read correctly.", "Nothing; the free project was funded because the larger limit moved the solve onto a coarse grid where zero capex rounds away."]'::jsonb, 0, 'Funded capex is 100.0000 against a limit of 101.0000, so 1.0000 stays unspent. The gap to the golden optimum closes to 0.0000.'),
  ('portfolio', 'beginner', 'module', 'm05-the-grid-under-the-answer', 14, 'In the three published free-project cases, at limits of 0.0000, 100.0000 and 101.0000, overLimit reads false. Why does the flag stay quiet where the engine loses 10.0000?', '["The flag counts cells rather than money, and a free project''s one cell is inside the limit in every case.", "EC5-0 repaired the free-project case, so the 10.0000 can no longer be lost.", "A set worth less than its exact optimum raises overLimitBy instead, which reads 10.0000 in two of the three cases.", "The engine''s set is inside the limit in money every time, and the flag only watches for a set over it."]'::jsonb, 3, 'The engine funds nothing, then A alone, then both, always within the limit. Finding D2 is left as it was, so a positive-EMV project with capex 0.0000 left out has to be noticed by hand.'),
  ('portfolio', 'beginner', 'module', 'm05-the-grid-under-the-answer', 15, 'The engine gives a user running their own coarse-grid inventory no gap to the exact optimum. Where did the golden''s 860.0000 on gridUndershoot come from?', '["The engine''s own exact re-check in money, which it runs and prints beside the answer whenever the reported resolution is not 1.0000.", "The test suite solved the exact problem separately; the engine never tests its answer against the unrounded capexes.", "The overLimitBy field, read as the value a larger limit would have added to the funded set.", "The Suite''s resolution display, which shows the gap to the exact optimum whenever the grid turns coarse."]'::jsonb, 1, 'A user sees 660.0000 and a clean flag, and the 200.0000 left out is found only by checking the unrounded capexes in money.'),
  ('portfolio', 'beginner', 'module', 'm06-the-associate-reading', 1, 'OK-3 has a pos of 0.250000, a success-case NPV of 420.0000 million USD and a fail_cost of 85.0000. What is it worth to the programme?', '["420.0000, the value the well delivers when it works, which is the outcome an exploration programme is drilled for.", "The chance-weighted success case with the 85.0000 fail cost left out, because the loss is already sunk in the capex.", "The success case less the fail cost, weighted by pos, which charges the 85.0000 only in the case the well works.", "41.2500 risked, 0.098214 of its success-case NPV."]'::jsonb, 3, '0.250000 x 420.0000 - 0.750000 x 85.0000 = 41.2500. Success-case NPV is what happens if the well works; risked EMV is what the chance of it working is worth.'),
  ('portfolio', 'beginner', 'module', 'm06-the-associate-reading', 2, 'Step one of the method compares a hand-risked EMV with the explorer''s column, and a row disagrees. What does the method say a mismatch means?', '["The explorer''s value comes from the seeded Monte Carlo, so it differs from the closed form by simulation noise at 10000 iterations.", "An input was typed wrong or a clamp fired: a pos over 1 read as 1, a pos under 0 as 0, or a negative fail_cost as 0.", "The explorer discounts the fail cost over the project life, which a hand calculation in one line cannot reproduce.", "The grid rounded the project''s value to a whole cell, and the hand value is the unrounded figure."]'::jsonb, 1, 'Risked EMV is closed form, pos x npv_p50 - (1 - pos) x fail_cost. The published posAboveOneClamps case reads a pos of 1.4 as 1 and returns 80.0000.'),
  ('portfolio', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Ranked by risked EMV per million USD, OK-3 comes last at 0.458333, yet the optimizer funds it at 450.0000. Why?', '["It fills the space the ranking leaves: swapping OK-5 for OK-3 adds 3.2500 for 30.0000 and lifts 287.7500 to 291.0000.", "Its success-case NPV of 420.0000 is the largest in the inventory, and the optimizer breaks near-ties toward upside.", "The ranking is computed on success-case NPV, and on risked EMV OK-3 actually ranks first per million USD.", "The optimizer funds the cheapest projects first, and OK-3''s 90.0000 is the lowest capex left after OK-5."]'::jsonb, 0, 'Greedy funds OK-1, OK-4 and OK-5 at 420.0000 for 287.7500 and cannot use the last 30.0000. The best set is not the best projects.'),
  ('portfolio', 'beginner', 'module', 'm06-the-associate-reading', 4, 'OKONO''s grid is exact at 1.0000. On an inventory whose resolution is anything else, which checks does the method require even when overLimit reads false?', '["None beyond the flag, since EC5-0 added overLimit precisely so that a coarse answer could be quoted without checking.", "Re-run the optimizer at a finer resolution chosen on request, and quote whichever answer has the larger EMV.", "Sum the funded capex against the limit in money, look for a left-out project that would still fit, and look for an unfunded positive-EMV project with capex 0.0000.", "Compare the funded set with the frontier''s last point, since the two disagree whenever rounding has moved the answer."]'::jsonb, 2, 'overLimit catches only the overshoot, 2.0000 on gridOvershoot. The undershoot that left 200.0000 out and the free project charged a cell worth 10.0000 are both silent.'),
  ('portfolio', 'beginner', 'module', 'm06-the-associate-reading', 5, 'A graded question solves OKONO at 450.0000 and then at 600.0000. Two shortcuts tempt: add OK-5 to the smaller set, or cut OK-2 from the larger one. How do they compare with solving each budget afresh?', '["Adding OK-5 reaches 402.7500 exactly, since the larger optimum is the smaller one with the projects that fit added on.", "Cutting OK-2 reaches 291.0000 exactly, because the smaller optimum is always a subset of the larger one.", "Adding OK-5 reaches 329.0000 against 402.7500, and cutting OK-2 reaches 287.7500 against 291.0000; both fall short.", "Both reach their budget''s optimum, since two budgets on one frontier share every funded set up to the smaller limit."]'::jsonb, 2, '291.0000 plus 38.0000 is 329.0000 at 510.0000, and 402.7500 less 115.0000 is 287.7500. OK-3 is in one optimum and not the other, so the sets are not nested.'),
  ('portfolio', 'beginner', 'module', 'm06-the-associate-reading', 6, 'Step six quotes the 450.0000 set''s risk as P(loss) 0.123600. Why must the seed and the iterations be quoted beside it?', '["The figure is counted from a seeded Monte Carlo, seed 20260829 and 10000 iterations here, and the seed and count are what make it reproducible.", "They record the normal approximation''s inputs, from which P(loss) is computed in closed form like risked EMV.", "They identify the grid the optimizer solved on, which decides the funded set whose risk is being reported.", "They are how the engine turns a probability into a percentile, so that 0.123600 can be quoted as the programme''s P90."]'::jsonb, 0, 'emv and stdDev are closed form, while probLoss, p90 and p10 come from the simulation. The 600.0000 set on the same seed and iterations reads 0.001800.'),
  ('portfolio', 'beginner', 'module', 'm06-the-associate-reading', 7, 'OKONO''s 450.0000 set shows a P90 of -18.3574 million USD. What does that number say?', '["There are nine chances in ten that the programme loses 18.3574, since the label names the probability of the loss it prints.", "The high case of the programme, the value beaten only one time in ten, so the programme is expected to lose money.", "A cost overrun of 18.3574 on the funded capex in the low case, since the simulation draws spending as well as value.", "The low case of simulated portfolio NPV is a loss, which fits a P(loss) of 0.123600."]'::jsonb, 3, 'P90 under the exceedance convention is the 10th percentile of simulated NPV. The 600.0000 set''s P90 of 200.3575 sits well above zero, beside a P(loss) of 0.001800.'),
  ('portfolio', 'beginner', 'module', 'm06-the-associate-reading', 8, 'One inventory has a row with a capex of -150, and another has a row with a negative risked EMV. What does the engine do with each?', '["It clamps the negative capex to 0 and funds the row free, and funds the negative row only if the budget is large enough.", "It refuses the first run with a PortfolioInputError, and solves the second but never funds the negative row.", "It refuses both, since a negative number anywhere in a project row is an invalid input the engine will not solve.", "It solves the first with the capex read as a refund that adds to the limit, and drops the second before solving."]'::jsonb, 1, 'A negative capex such as -150 is refused outright. The published negativeEmvHugeBudget case leaves its row at -44.0000 out even at a limit of 10000.0000.'),
  ('portfolio', 'beginner', 'module', 'm06-the-associate-reading', 9, 'OFON-1''s budget is 27050000 and OKONO''s limit is 450.0000. Why does the method never set one against the other?', '["They are different models: OKONO is a capital inventory in million USD across projects, OFON-1 an AFE in whole USD across cost lines.", "They can be compared once OFON-1 is divided by a million, since both are dollars and the AFE is simply one project''s spend.", "OFON-1 is the AFE for OK-1, so its budget is a line inside OKONO''s limit and must not be counted twice.", "The AFE budget moves with the as-of date while the limit is fixed, so the two are never read on one date."]'::jsonb, 0, 'The two share nothing: OFON-1 runs a window from 2027-02-01 to 2027-11-30 across five cost lines, and its numbers are never mixed with OKONO''s.'),
  ('portfolio', 'beginner', 'module', 'm06-the-associate-reading', 10, 'OFON-1''s line CSG-02 has spent 4300000 against a budget of 3900000 with no entered forecast. What does it forecast, and why?', '["3900000, since a line with no entered forecast carries its budget as its forecast until one is typed.", "The actual less the budget, the overrun alone, since a forecast reports only what remains to be spent on the line.", "Nothing until a forecast is entered, since the forecast rule refuses a line whose forecast is not positive.", "4300000, the larger of its budget and its actual plus commitment."]'::jsonb, 3, 'The AFE''s estimate at completion is 27600000, a variance at completion of -550000. A forecast copied from the budget would hide CSG-02''s overrun, which the Suite did before EC5-0 whenever a line was edited.'),
  ('portfolio', 'beginner', 'module', 'm06-the-associate-reading', 11, 'OFON-1 earns 15231500 with CPI 1.009377 at 2027-06-30 and again at 2027-08-15, while SPI reads 1.141290 and then 0.872063. Why does only SPI move?', '["CPI is actuals over earned value and is fixed at the start of the window, while SPI is recomputed each month from the invoices received to date.", "Progress was re-entered between the two reports, which moves SPI but not CPI because CPI ignores progress.", "Earned value and actuals do not depend on the date; planned value comes from the calendar, so SPI changes with the as-of date.", "SPI is read from the S-curve, whose forecast jumps after the as-of date, while CPI is read from the budget and the actuals, which no date can change."]'::jsonb, 2, 'CPI is earned value over actuals, 15231500 over 15090000 at every date. Planned value rises through the window, so the same earned value reads ahead in June and behind in August.'),
  ('portfolio', 'beginner', 'module', 'm06-the-associate-reading', 12, 'OFON-1''s S-curve ends with a Planned point of 24452483 against a budget of 27050000. What does the shortfall mean?', '["An underspend of the plan, since the budget was phased to finish below its total and the rest is held as contingency.", "Nothing at the well: the curve is built in monthly buckets and stops at the window end, short of the full budget.", "The work running behind schedule by that amount, since a Planned point below budget means progress fell short.", "A curve that keeps walking past the end date, which moves the final month''s plan into the following year."]'::jsonb, 1, 'The last Planned point is 24452483, and past the as-of date the forecast jumps from the last actual of 15090000 to 19374834. Neither the shortfall nor the jump is an event at the well.'),
  ('portfolio', 'beginner', 'module', 'm06-the-associate-reading', 13, 'A report states only ''SPI 0.872063'' and ''funded set worth 291.0000''. What is missing from each figure?', '["Its seed and iterations, as though both were simulated.", "Its unit alone, since USD for the SPI and million USD for the set would settle both readings.", "Its sign convention, since SPI and risked EMV both invert when the reporting currency changes.", "Its basis: the as-of date 2027-08-15 for the SPI and the limit 450.0000 for the funded set."]'::jsonb, 3, 'An SPI read with no date means nothing: OFON-1 reads 1.141290 at 2027-06-30 and 0.872063 at 2027-08-15. A funded set is the answer at one limit, and at 600.0000 the value is 402.7500.'),
  ('portfolio', 'beginner', 'module', 'm06-the-associate-reading', 14, 'Every step of the method checks out on OKONO at 450.0000: rows risked by hand, resolution 1.0000, the set proven at 291.0000 and the greedy set beaten. What does that still not prove?', '["That the inputs were right: the arithmetic is proven, but no step can show that a pos or a fail_cost was a good estimate.", "That the set is the optimum, since a proof by hand covers only the three funded projects and says nothing about the three left out of the set.", "That the frontier''s last point matches the funded set, which only the Monte Carlo can confirm.", "That the grid was exact, since a resolution of 1.0000 can still round a capex typed with decimals."]'::jsonb, 0, 'The method funds projects whole, uses one average correlation and assumes a normal success spread. OK-3''s 41.2500 is only as good as its pos of 0.250000 and its fail_cost of 85.0000.'),
  ('portfolio', 'beginner', 'module', 'm06-the-associate-reading', 15, 'OK-3 is out of the OKONO set at 300.0000, in at 450.0000, out at 600.0000 and back at 750.0000. What does that path show?', '["OK-3 is marginal at 0.458333 per million USD, so the optimizer rotates it in and out of the funded set to spread the exploration risk across budgets.", "Each budget is solved afresh over the whole inventory, so a project''s place in one funded set promises nothing at another limit.", "The grid rounds OK-3''s 90.0000 differently at each limit, which moves it across the edge of the knapsack.", "The optimizer builds each larger set on the one before and removes OK-3 whenever a better project is added."]'::jsonb, 1, 'At 450.0000 OK-3 fills the 30.0000 greedy leaves, for 291.0000; at 600.0000 the set is OK-1, OK-2, OK-4 and OK-5 at 402.7500 without it. On OKONO''s exact grid of 1.0000 nothing is rounded.'),
  ('portfolio', 'beginner', 'final', null, 1, 'An analyst retypes OKONO''s inventory with every capex and the limit as a count of USD instead of million USD, and changes nothing else. What changes in how the engine solves it, and where would the analyst see the change?', '["Nothing changes in the solve, because risked EMV per million USD is a ratio whose unit cancels, so the ranking and the set come out identical.", "The engine refuses the run with a PortfolioInputError, since a capex that large beside NPVs in million USD fails the engine''s scale check.", "The limit is no longer at most 5000, so the grid turns coarse at the limit divided by 2000 per cell, and only the reported resolution shows the switch.", "The grid stays at 1 million USD per cell but every project now weighs a million times more cells, so none of them fits under the limit and nothing is funded at all."]'::jsonb, 2, 'The exact grid needs whole numbers and a limit of at most 5000; the published rawDollars case runs on a cell of 225000.000000 USD and still reaches the exact 250.0000, with a gap of 0.0000.'),
  ('portfolio', 'beginner', 'final', null, 2, 'A board minute says the optimizer picked the safe portfolio when it chose OKONO''s 600.0000 set over its 450.0000 one. What role did the simulated loss probabilities play in selecting either set?', '["None: the optimizer and the frontier rank on risked EMV alone, and the seeded risk summary is computed afterwards for the set already chosen.", "They broke a near tie, because the engine penalises each set''s risked EMV by its simulated loss probability before comparing it with the rest of the frontier.", "They screened the inventory, since any project whose failure branch lifts a set''s P(loss) above the default is dropped before the knapsack runs.", "They decided OK-3, which the simulation found worth its risk at 450.0000 and not worth it at 600.0000, where a safer set was available."]'::jsonb, 0, 'The 600.0000 set wins because 402.7500 beats every other set that fits, not because it is safer; a lower-risk set of nearly equal value is never offered.'),
  ('portfolio', 'beginner', 'final', null, 3, 'OKONO''s 450.0000 set totals 725.0000 of success-case NPV and its 600.0000 set only 473.0000. Why does the larger budget fund less success NPV?', '["The larger frontier is solved on a coarser grid, so the success cases of the funded projects are rounded down to whole cells before they are summed.", "Success NPV is capped at the limit, so a larger budget spreads the same cap over more projects.", "The optimizer at 600.0000 trades success NPV for a lower P(loss), which is why the safer set carries less upside than the riskier one.", "OK-3 and its 420.0000 success case leave the set at 600.0000, and the optimizer maximises risked EMV, which rises to 402.7500."]'::jsonb, 3, 'Success NPV adds every best case as if all worked at once; risked EMV goes from 291.0000 to 402.7500 while success NPV falls, and only risked EMV is maximised.'),
  ('portfolio', 'beginner', 'final', null, 4, 'A risky project''s chance of success is left blank in an inventory. Beyond its risked EMV, what does the blank do to the seeded risk summary of a set that funds it?', '["Nothing, since the simulation draws its own success rate from the entered percentiles whatever pos says, and only the optimizer uses the default.", "The default of 1 travels into the simulation, so the project succeeds in every iteration, never adds a failure to P(loss) and never drags down the P90.", "The simulation refuses to run for that set and reports P(loss) as null until a chance of success is entered for every funded project.", "The simulation treats the blank as a coin toss and draws success half the time, so the set looks riskier than its risked EMV would suggest."]'::jsonb, 1, 'A defaulted value is used everywhere the project is used; at seed 20260829 and 10000 iterations the project is a certain success, so one blank row makes a set look both more valuable and safer.'),
  ('portfolio', 'beginner', 'final', null, 5, 'A study already paid for elsewhere is added to OKONO as a project with capex 0.0000 and a positive risked EMV, and the limit stays at 450.0000. Can the engine''s answer hold it together with OK-1 + OK-3 + OK-4?', '["Yes, because a project with capex 0.0000 weighs nothing on any grid and rides along with every set whose risked EMV it raises.", "Yes, but only with overLimit true and overLimitBy of 1 million USD, since the engine lets a free project squeeze in over a limit that is already spent.", "No: the grid charges it one cell, and OK-1 + OK-3 + OK-4 already use all 450.0000 cells, so no spare cell is left for it.", "No, because a capex of 0.0000 is refused by the check that stops a negative capex."]'::jsonb, 2, 'Every project weighs max(1, round(capex / cell)) cells, finding D2; in freeProjectTightLimit the same effect costs 10.0000 of EMV at a limit of 100.0000 while overLimit stays false.'),
  ('portfolio', 'beginner', 'final', null, 6, 'The greedy walk down OKONO''s EMV per million ranking at 450.0000 stops at OK-1 + OK-4 + OK-5. Where does that set sit on the efficient frontier?', '["Below the frontier, since a set built from a ranking is always beaten at its own capex by some solved set of whole projects.", "On point 11, level with the optimum, since both sets report the frontier''s last value once rounding to cells is allowed for.", "Nowhere, since the frontier records only sets that spend the whole limit, and the greedy set leaves 30.0000 of it unspent.", "On point 10, the best set for 420.0000, one step short of the answer."]'::jsonb, 3, 'Point 10 is 420.0000 and 287.7500; the last step swaps OK-5 for OK-3 and adds 3.2500 for 30.0000 to reach 291.0000.'),
  ('portfolio', 'beginner', 'final', null, 7, 'Two answers leave money idle: OKONO at 750.0000 spends 690.0000, and the gridUndershoot case spends 4500.0000 of 6000.0000. Why is only the second a reason to distrust the set?', '["The second leaves a quarter of its limit idle and the first under a tenth, and the engine marks an answer unreliable once idle money passes a set share of the limit.", "OKONO solves on an exact grid and its one left-out project, OK-6 at 310.0000, cannot fit, while the undershoot runs on a coarse grid where rounded-up weights squeezed out W, which fits in money.", "The undershoot reports overLimit true, which marks a grid problem, while OKONO at 750.0000 reports false and so needs no further check by the reader.", "Both are equally suspect, since money left unspent always means the knapsack stopped early and a better set of whole projects exists somewhere."]'::jsonb, 1, 'The golden gap of -200.0000 is exactly W''s risked EMV and no flag reports it (finding D4); OKONO''s 60.0000 is genuine because nothing that remains fits.'),
  ('portfolio', 'beginner', 'final', null, 8, 'In tieDifferentComposition the engine returns A for 80.0000 where B + C also reaches 80.0000. What would a reviewer need in order to compare the P(loss) of the two sets?', '["A separate simulation of B + C, because the engine''s risk summary covers only the set it returned and its output names no alternative optimum.", "Nothing extra, since the risk summary averages P(loss) over every set that ties on risked EMV and reports the blended figure beside the funded set.", "Nothing extra, since tied sets share their risked EMV and therefore share their P(loss) and their P90 as well, whatever projects they hold.", "A rerun on a finer grid, since the engine lists alternative optima in its output only when the resolution drops below 1.0000."]'::jsonb, 0, 'The knapsack keeps the first set it builds and replaces it only with a strictly larger EMV; A is one bet and B + C spreads the same 80.0000 over two, so their risk can differ widely.'),
  ('portfolio', 'beginner', 'final', null, 9, 'Three inventories each hide a problem: a capex typed as -150, a coarse grid that funds 6002.0000 against 6000.0000, and a coarse grid that leaves out a project worth 200.0000. How does the engine treat each?', '["It refuses all three, because each one breaks a condition the knapsack needs before it can honestly return a set under the limit.", "It flags the first and second through overLimit, and flags the third by printing a negative gap to the exact optimum beside the set.", "It refuses the first and the second, since a set over the limit is rejected like a negative capex, and reports the third as money unspent.", "It refuses the first, flags the second with overLimit true, and says nothing about the third."]'::jsonb, 3, 'The only refusal is a negative capex; the overshoot flag reads overLimitBy 2.0000, and the undershoot''s -200.0000 gap exists only in the golden, never in the engine''s output.'),
  ('portfolio', 'beginner', 'final', null, 10, 'Working a graded inventory, a candidate finds the reported resolution is not 1.0000. Which checks does the Associate method require before the funded set is quoted?', '["Confirm that overLimit reads false, since a coarse grid can only go wrong by overshooting and the repaired flag now reports every overshoot.", "Rerun with a smaller limit until the resolution returns to 1.0000, since the engine offers its exact grid on request once asked.", "Sum the funded capex in money against the limit whatever overLimit says, look for a left-out project that would still fit, and look for an unfunded positive project with capex 0.0000.", "Nothing extra, since both published coarse cases, rawDollars and nonIntegerLimit, reached the exact optimum with a gap of 0.0000."]'::jsonb, 2, 'A coarse grid can overshoot, which is flagged, or undershoot or charge a free project a cell, which are silent (findings D4 and D2); only gridOvershoot''s overLimitBy 2.0000 is reported.'),
  ('portfolio', 'beginner', 'final', null, 11, 'A reviewer who counts rows from one opens an inventory without names or ids after a PortfolioInputError that blames Project "1" for a capex of -0.5. Which row holds the bad capex?', '["The first project in the list, since the engine numbers its rows from one in the same way the Suite''s inventory table does.", "The second project in the list, since an unnamed project is named by its position counted from zero.", "Any project with a capex of -0.5, since the number in quotes counts the refused projects rather than naming a position.", "No row at all, since a capex of -0.5 rounds to zero cells and the message is a warning that the run continues past."]'::jsonb, 1, 'The message names a project by name, then id, then position from 0, and the check runs before any set is chosen, so no partial answer comes back.'),
  ('portfolio', 'beginner', 'final', null, 12, 'A geologist enters OK-3''s npv_p50 as 41.2500 because that is what the well is worth, and keeps pos at 0.250000 and fail_cost at 85.0000. What has gone wrong?', '["The well is risked twice, and with 0.750000 x 85.0000 now outweighing a quarter of 41.2500 its risked EMV turns negative, so it is never funded.", "Nothing, since the engine sees a success case smaller than the fail cost and restores the entered npv_p10 of 700.0000 as the success case.", "Only the spread moves, because npv_p10 and npv_p90 are rescaled around 41.2500, while the well''s risked EMV of 41.2500 stays as entered.", "The well is valued at 41.2500 as intended, because the optimizer reads npv_p50 directly and pos enters only the Monte Carlo draws."]'::jsonb, 0, 'npv_p50 is the success case, 420.0000 for OK-3, and the one line applies pos to it; a value already risked is discounted again and the failure branch dominates.'),
  ('portfolio', 'beginner', 'final', null, 13, 'The workovers'' two spread measures agree exactly and the exploration well''s do not. What makes the well''s mixture standard deviation the wider of its pair?', '["The mixture uses an explicit npv_stddev where one is entered, and OK-3 carries one while OK-5 falls back to its entered percentiles.", "The success spread is taken from npv_p10 less npv_p90 and the mixture from npv_p10 less npv_p50, which is wider for a well with a long upside.", "The mixture counts the drop from a success to a loss of 85.0000 three times in four, and OK-5 cannot fail, so it has no such drop.", "The mixture adds the capex of 90.0000 as a second source of variance, and OK-5''s capex is too small against its NPV to register."]'::jsonb, 2, 'The success spread describes the well only when it works, (700.0000 - 210.0000) / 2.5631 = 191.1747; failure widens the range, and fail costs set the floor of every simulated outcome.'),
  ('portfolio', 'beginner', 'final', null, 14, 'Two rows enter percentiles of 200 and 50: one as npv_p10 200 and npv_p90 50, the other with the two swapped. Which row is more dangerous, and why?', '["The first, since its spread of 58.5229 exceeds the explicit 40.0000 the engine would prefer and so overstates the risk summary.", "Neither, since the engine sorts the two percentiles before it divides, so both rows return a spread of 58.5229.", "The swapped row, because the engine refuses inverted percentiles with a PortfolioInputError and the set can then not be solved at all.", "The swapped row, whose spread of 0.0000 silently removes its success range from the risk summary."]'::jsonb, 3, 'In the right order the spread is (200 - 50) / 2.5631 = 58.5229; inverted, the published case returns 0.0000 with no error, because nothing checks that npv_p10 sits above npv_p90.'),
  ('portfolio', 'beginner', 'final', null, 15, 'A greedy analyst funds OKONO straight down its ratio table until the money for 450.0000 runs out. Which candidate is the earliest one passed over, and why?', '["OK-3, since its 0.458333 is the lowest ratio and a greedy walk never reaches it.", "OK-2, because after OK-1 and OK-4 reach 360.0000 its 180.0000 would take the total to 540.0000.", "OK-6, because at 310.0000 it is the largest capex in the inventory and could not fit beside OK-1 at any stage of the walk.", "OK-5, since after OK-1, OK-4 and OK-2 reach 540.0000 no room remains."]'::jsonb, 1, 'The walk then adds OK-5 for 420.0000, and neither OK-6 nor OK-3 fits the 30.0000 left, so it ends at 287.7500 against the optimizer''s 291.0000.'),
  ('portfolio', 'beginner', 'final', null, 16, 'A planner argues the greedy ranking must be sound because at 600.0000 it fills the budget exactly and matches the optimizer. What does that coincidence establish about other budgets?', '["That a ranking is exact whenever it spends the whole limit, which it misses at 450.0000 only because 30.0000 of that limit is left idle.", "That the optimizer runs the ranking itself, so its 291.0000 at 450.0000 is a rounding artefact.", "Nothing: the same ranking loses 3.2500 at 450.0000, and nothing in a ranking says in advance which budgets it will fill.", "That the frontier''s step ratios fall steadily past 450.0000, which is the condition under which a ranking always fills a budget."]'::jsonb, 2, 'At 600.0000 the walk funds OK-1, OK-4, OK-2 and OK-5 for 402.7500, the optimizer''s own set; at 450.0000 it stops at 287.7500, and only solving the set tells the two budgets apart.'),
  ('portfolio', 'beginner', 'final', null, 17, 'A licence commitment must be drilled although its risked EMV is negative. How does an analyst get it into OKONO''s programme?', '["Take its capex off the limit before the run and optimise the rest, because the engine has no must-fund flag and never funds a project at 0 or less.", "Raise the limit until the optimizer has room, since negativeEmvHugeBudget shows that a large enough budget eventually funds everything that fits.", "Enter a pos of 1.4 so the clamp lifts it to certain success, which is the supported way to mark a project as mandatory.", "Leave it in the inventory as it is, since the optimizer spends any unspent money on the next project whatever its value."]'::jsonb, 0, 'In negativeEmvHugeBudget a limit of 10000.0000 funds good + better for 120.0000 and still leaves the negative project out; funding it lowers expected value by exactly its negative EMV.'),
  ('portfolio', 'beginner', 'final', null, 18, 'zeroEmvExcluded holds a project whose risked EMV is exactly 0.0000, under a limit of 500.0000 with room to spare. Why does the engine leave that project out?', '["The engine treats a risked EMV of exactly zero as a missing value and refuses the row before the knapsack starts.", "The grid charges every project a cell, and a project worth zero can never win that cell against the good project.", "It is an input error the engine corrected by a clamp, since any risked EMV below its fail cost is read as zero.", "It adds nothing to the objective and would still use capex."]'::jsonb, 3, 'The engine funds good alone for 50.0000 and 30.0000; a project at 0 or less is never funded, and money may be left unspent.'),
  ('portfolio', 'beginner', 'final', null, 19, 'An auditor wants to export the 60.0000 that OKONO''s five-project answer at 750.0000 leaves idle. Which part of the engine''s return carries it?', '["As overLimitBy with a negative sign, since that flag measures the distance between the funded capex and the limit on either side.", "Nowhere as a field: the engine returns the limit, the set, its capex and its EMV, and the reader derives the unspent amount by subtraction.", "As the resolution, which rises to 60.0000 whenever a limit cannot be spent exactly in whole projects on the exact grid.", "As a partial slice of OK-6, which the engine funds with the leftover money and reports beside the five whole projects."]'::jsonb, 1, 'Every unspent figure is derived, 750.0000 - 690.0000 = 60.0000, and it is genuine because OK-6 alone costs 310.0000; the frontier''s last point is printed at 690.0000, not at the limit.'),
  ('portfolio', 'beginner', 'final', null, 20, 'tieIdenticalProjects funds twinA, and the golden accepts twinA or twinB. If the inventory is re-sorted so twinB is entered first, what should a reviewer expect?', '["twinA again, since ties are broken by the alphabetical order of project ids before the knapsack begins building sets.", "Both twins, since a limit of 100.0000 holding two sets of 50.0000 funds the pair and reports 100.0000 of risked EMV.", "twinB can come back instead, because the knapsack keeps the first best set it builds and an equal set found later never displaces it.", "An error, since the engine refuses any inventory in which two different sets tie on the objective."]'::jsonb, 2, 'The output has no field for alternative optima, so entry order decides between tied sets; nothing in the inputs separates the twins at 50.0000.'),
  ('portfolio', 'beginner', 'final', null, 21, 'A budget of 150.0000 is proposed for OKONO, halfway between the frontier points at 120.0000 and 180.0000. What is the best risked EMV it buys?', '["89.7500, the lower point''s value, since no whole set between those two capexes does better.", "The midpoint of 89.7500 and 127.7500, read along the straight line the chart draws between those two frontier points.", "127.7500, since OK-1 and OK-5 together fit once the budget passes the halfway mark between the points.", "A share of the 38.0000 the next step adds, priced at that step''s 0.633333 per extra million USD."]'::jsonb, 0, 'The frontier is a staircase of whole sets; every budget from 120.0000 to just short of 180.0000 buys exactly OK-1''s 89.7500.'),
  ('portfolio', 'beginner', 'final', null, 22, 'Step 3 of OKONO''s frontier reads 1.616667 per extra million USD, while OK-1 earns 0.747917 per million of its own capex. Why are the two so different?', '["Step 3 counts OK-1''s success-case NPV where the project ratio uses its risked EMV, so the step overstates the project.", "Step 3 is measured in the frontier''s cells while the project ratio uses million USD, and each cell there is worth more.", "Step 3 adds OK-1 on top of OK-3, so its gain counts OK-3''s risked EMV a second time beside OK-1''s own.", "Step 3 is the swap of OK-3 for OK-1, gaining 48.5000 for 30.0000."]'::jsonb, 3, '89.7500 less 41.2500 is 48.5000 over 120.0000 less 90.0000; only a step that adds a project on top reads as that project''s ratio, as steps 4 and 10 show OK-5''s 0.633333.'),
  ('portfolio', 'beginner', 'final', null, 23, 'A reviewer sees the frontier''s smallest gain recur on three separate steps and suspects the grid is repeating itself. What does each of those steps actually trade?', '["OK-3 added on top of a smaller set, its 41.2500 split across three budgets in the pieces the grid allows.", "The same trade: OK-5 out and OK-3 in, 41.2500 less 38.0000 for 90.0000 less 60.0000.", "Three different trades that coincide because every capex is a multiple of 30.0000.", "A rounding step the exact grid inserts when no whole project fits."]'::jsonb, 1, 'At point 11 that swap turns the greedy set''s 287.7500 into the optimum''s 291.0000, so its ratio of 0.108333 does not mean the last 30.0000 was badly spent.'),
  ('portfolio', 'beginner', 'final', null, 24, 'A sponsor offers OKONO a single extra million on top of the 450.0000 limit, citing the 0.733333 per extra million USD that the next frontier step reads. What does that million add?', '["0.733333, the next step''s ratio, bought a million at a time as the budget climbs toward the next point.", "0.108333, the ratio of the step just taken, which is the best available estimate of what the next million returns.", "0.0000 more, since the value stays at 291.0000 until the budget reaches 480.0000, where it steps to 313.0000.", "A share of OK-5, whose 0.633333 per million is the cheapest way to put a small increment on top of the optimum."]'::jsonb, 2, 'The ratio 0.733333 is 22.0000 over 30.0000, an average across a whole step; no project is funded in part, so a million inside a step buys nothing.'),
  ('portfolio', 'beginner', 'final', null, 25, 'Told to trim OKONO''s 600.0000 programme back to 450.0000, a manager strikes the gas compression project and keeps the rest. How does the trimmed programme compare with re-solving?', '["It leaves OK-1 + OK-4 + OK-5 at 420.0000 for 287.7500, 3.2500 short of the 291.0000 re-solving finds by bringing back OK-3.", "It reaches the re-solved answer, because optimal sets are nested across budgets.", "It beats re-solving, because the manager keeps OK-5, the one certain project, where the optimizer would trade it for a riskier well.", "It matches the re-solved value with a different set, since both reach 291.0000 and the engine breaks such a tie by entry order."]'::jsonb, 0, 'No single drop from the 600.0000 set reaches the 450.0000 answer, because that answer holds OK-3, which the larger set left out.'),
  ('portfolio', 'beginner', 'final', null, 26, 'Handed a raised budget of 600.0000, a manager tops up the solved 450.0000 set with whatever else fits rather than re-running the optimizer. Where does topping up stop?', '["At 402.7500, since adding in ratio order to a solved set reaches the next one.", "At 329.0000 for 510.0000, with OK-5 added and nothing else fitting, against 402.7500 from solving again.", "At 444.0000, with OK-2 and OK-5 both added, since the extra 150.0000 of budget covers the pair of them together.", "At 291.0000, since the engine refuses a project added to a solved set by hand."]'::jsonb, 1, 'After OK-5 only 90.0000 is left and OK-2 costs 180.0000; the solved set at 600.0000 gives up OK-3 to fund OK-1 + OK-2 + OK-4 + OK-5.'),
  ('portfolio', 'beginner', 'final', null, 27, 'Both OKONO frontiers pass through the same first dozen points up to 450.0000 and 291.0000. What does that agreement prove, and what does it leave unproven?', '["It shows the 600.0000 answer contains the 450.0000 answer, since the longer frontier is built by extending the shorter one.", "It shows nothing, because the second frontier is solved on a coarser grid and agrees with the first only through rounding.", "It shows the extra 150.0000 goes to the same projects in the same order, which is why the first points agree.", "The best value at each budget nests; the winning set at the larger limit does not."]'::jsonb, 3, 'Both frontiers pass through 450.0000 and 291.0000, yet OK-3 is funded at 450.0000 and dropped at 600.0000, where OK-1 + OK-2 + OK-4 + OK-5 reach 402.7500.'),
  ('portfolio', 'beginner', 'final', null, 28, 'A report shows OKONO''s frontier ending at 450.0000 and 291.0000 beside a funded set worth 287.7500. What should the reader conclude?', '["The funded set is the greedy set and the frontier is the optimum, which the engine prints side by side so the loss can be seen.", "The grid has undershot, and the 3.2500 between them is a project rounding left out.", "The two were not run on the same inventory and limit, so find which input changed before quoting either.", "The frontier includes projects the funded set excludes for risk, so its last point always sits a little above the set."]'::jsonb, 2, 'The last point is the best risked EMV inside the whole limit and must match the funded set; at 450.0000 both read OK-1 + OK-3 + OK-4 for 291.0000 on a resolution of 1.0000.'),
  ('portfolio', 'beginner', 'final', null, 29, 'rawDollars reports a resolution of 225000.000000 and nonIntegerLimit a resolution of 0.225250. What does a resolution measure?', '["The size of one capex cell in the money units entered, USD in the first case and million USD in the second.", "The precision of the risked EMV, so the second case''s answer is reliable to a far finer margin than the first''s.", "The number of cells the limit is divided into, which grows when the capexes are typed in USD.", "The standard error of the simulated P(loss), which the engine shrinks as the limit grows."]'::jsonb, 0, 'The coarse cell is the limit over 2000: 450000000.0000 over 2000 is 225000.000000 and 450.5000 over 2000 is 0.225250, and both still reach 250.0000 with a gap of 0.0000.'),
  ('portfolio', 'beginner', 'final', null, 30, 'In gridOvershoot, A weighs 1333 cells and B 667, together exactly the 2000 cells of a limit of 6000.0000. Why does the pair fit on the grid but not in money?', '["The limit of 6000.0000 is a whole number, so the grid is exact at 1 million USD per cell and the overshoot is only a rounding of the printed totals.", "Both capexes round down on a cell of 3.000000, B''s 2002.0000 included, so the pair weighs less in cells than the 6002.0000 it costs.", "The engine adds a tolerance of one cell to every limit, so that a set landing on the boundary of the grid is not lost to rounding.", "A is charged the minimum of one cell as a large project, so the grid undercounts it by nearly its whole capex of 4000.0000."]'::jsonb, 1, 'A limit over 5000 sends the grid coarse at 6000.0000 over 2000; the engine flags overLimit true and overLimitBy 2.0000 but still returns 800.0000, against 780.0000 for A + C, which truly fits.'),
  ('portfolio', 'beginner', 'final', null, 31, 'gridOvershoot''s golden gap is 20.0000 and gridUndershoot''s is -200.0000. What does the sign of each gap say about the engine''s set?', '["Both mean the grid was coarse by that many cells, with the sign recording only whether the capexes were rounded up or rounded down.", "A positive gap is a genuine improvement the coarse grid found over exact arithmetic, and a negative one is the grid''s unavoidable rounding cost.", "The engine prints both gaps beside overLimit so that a user running any inventory can see how far the run sits from the exact optimum.", "A positive gap means the set beat the exact optimum by breaking the limit; a negative one means a better fitting set was squeezed out."]'::jsonb, 3, 'The gap is the engine''s EMV less the exact optimum: 800.0000 less 780.0000, and 660.0000 less 860.0000, the second exactly W''s 200.0000.'),
  ('portfolio', 'beginner', 'final', null, 32, 'A capital committee cannot see why gridUndershoot''s four candidates, whose money totals sit inside its coarse limit, are never funded together. What stops the fourth?', '["The engine caps a funded set at three projects on a coarse grid, which keeps the knapsack inside its time budget.", "Z''s 1502.0000 is refused as over a per-project ceiling of 1500.0000, and the grid drops W with it as the least valuable.", "On a cell of 3.000000 every capex rounds up, and the four rounded weights need more than the 2000 cells the limit holds.", "The four together would overshoot in money, so the overshoot flag removes the cheapest project before the answer is reported."]'::jsonb, 2, 'W, X and Y weigh 500 cells each and Z 501, one cell more than 2000; the engine funds X + Y + Z for 660.0000 and overLimit reads false (finding D4).'),
  ('portfolio', 'beginner', 'final', null, 33, 'Between the tight and the slack free-project cases the only change is one extra million of limit, yet funded EMV rises by 10.0000 while funded capex does not move. What did that million pay for?', '["The free project''s capex, which the engine rounds up from 0.0000 to 1 million USD whenever a limit allows it.", "Only the cell the grid charges the free project; the money itself is never spent.", "A change of grid, since a limit of 101.0000 is coarse and every project''s weight in cells is recalculated.", "Nothing real, since both runs share one optimum and the 10.0000 between them is a tie the engine breaks by entry order."]'::jsonb, 1, 'The free project weighs max(1, round(capex / cell)), one cell (finding D2); at 100.0000 A uses every cell and the golden optimum of 70.0000 is missed by 10.0000.'),
  ('portfolio', 'beginner', 'final', null, 34, 'An inventory is typed entirely in USD instead of million USD. Why can a check of risked EMV per million of capex, project by project, never reveal the slip?', '["Both amounts sit in the same unit, so it cancels, and OK-1''s 0.747917 would come out of a USD inventory unchanged.", "The ratio prints to six decimals, which is too coarse to show a factor of a million between two inventories.", "The engine converts USD to million USD before computing risked EMV, so every ratio is taken on corrected numbers.", "The ratio divides by capex in grid cells, and a cell is the same size in either unit."]'::jsonb, 0, 'The engine holds no currency field, no unit field and no scale check; what a USD inventory does change is the grid, which turns coarse once the limit is over 5000.'),
  ('portfolio', 'beginner', 'final', null, 35, 'A candidate project spends its capex over three years, most of it in the last one. How does the portfolio engine represent that phasing?', '["It discounts later years at a rate implied by npv_p50, so it weighs less.", "It splits the project into one knapsack item per year, each funded whole.", "It does not: capex is one amount spent in one period, and no time value is added beyond the NPVs entered.", "It charges the full capex against the limit but only the first year''s share against the grid, at one cell per year of spend."]'::jsonb, 2, 'Projects are funded whole with capex never phased; OKONO''s 450.0000 limit is met by 120.0000 plus 90.0000 plus 240.0000 as single amounts.'),
  ('portfolio', 'beginner', 'final', null, 36, 'OK-3 costs 90.0000 to fund and loses 85.0000 if it fails. A modeller leaves fail_cost blank on the grounds that the engine already knows the capex. What does the engine use?', '["The capex of 90.0000, since a missing fail cost defaults to the money spent.", "A fail cost of 0, because fail_cost is typed and never inferred from capex, so the dry hole is valued as free.", "The success-case NPV with its sign reversed, since failure is modelled as losing the prize the well was drilled for.", "Nothing: the row is refused until a fail cost is entered, because the one line cannot be evaluated with a term missing."]'::jsonb, 1, 'A missing fail_cost defaults to 0; in missingNpvIsZero a typed fail_cost of 8 at pos 0.25 gives -6.0000, all of it from the failure branch.'),
  ('portfolio', 'beginner', 'final', null, 37, 'An asset team wants the optimizer to favour the steadier of two look-alike wells whose rows match everywhere except entered percentiles running twice as wide on one. What does the knapsack do with the pair?', '["It prefers the narrower one, because the one line subtracts the success spread from npv_p50 before weighting it by pos.", "It prefers the wider one, because a wider range raises npv_p10 and the one line counts upside above the success case.", "It funds the two together as a hedge, since the knapsack spreads a limit across projects whose ranges differ.", "As identical: the percentiles feed only the risk summary."]'::jsonb, 3, 'Risked EMV = pos x npv_p50 - (1 - pos) x fail_cost, so equal inputs give equal EMVs; where only one fits, entry order decides, as in tieIdenticalProjects.'),
  ('portfolio', 'beginner', 'final', null, 38, 'A slide divides OFON-1''s estimate at completion of 27600000 by OKONO''s limit of 450.0000 to show the AFE''s share of the capital programme. What is wrong with it?', '["The two models share nothing: OKONO is a capital inventory in million USD and OFON-1 an AFE in whole USD, so the ratio mixes units and describes no real programme.", "Nothing is wrong, since both figures are amounts of planned spend, and a forecast from one model can be read against a limit from the other.", "The estimate at completion should carry a P-label first, since it is a percentile of cost and must be named before any comparison.", "The limit should be replaced by the 291.0000 of risked EMV, since a share of a programme is measured against its value."]'::jsonb, 0, 'This question examines the mix itself: OKONO''s 450.0000 is million USD and OFON-1''s 27600000 is USD, and the course never divides one model''s numbers by the other''s.'),
  ('portfolio', 'beginner', 'final', null, 39, 'The Associate reading closes on OFON-1: as of 2027-08-15 its CPI is 1.009377 and its SPI 0.872063. Which of the two would read differently on a report dated another day inside the window?', '["CPI, because actual cost is read at the as-of date, while SPI is fixed once the progress on each line has been entered.", "Both of them, since each index is a ratio to planned value and planned value is read from the calendar.", "SPI, because planned value comes from the calendar, while CPI rests on an earned value of 15231500 that is the same at every as-of date.", "Neither of them, since both indices are computed once when the AFE is created and stored against each line."]'::jsonb, 2, 'OFON-1 earns 15231500 at every as-of date with CPI 1.009377; SPI is 1.141290 at 2027-06-30 and 0.872063 at 2027-08-15.'),
  ('portfolio', 'beginner', 'final', null, 40, 'A capstone answer writes P90 capex 450.0000, P90 NPV -18.3574 and P(loss) 0.123600. Which P-label is used correctly?', '["Only the P90 on the capex, since a capex is an estimate and estimates take the exceedance convention while outcomes do not.", "Only the P90 on the NPV, the low case of simulated portfolio NPV at seed 20260829.", "Both, since P90 names the value exceeded nine times in ten, cost or NPV.", "Neither, since the engine''s P90 is the high case of NPV."]'::jsonb, 1, 'This examines a mislabel: P-labels belong to a portfolio NPV outcome alone, with P90 the low case, and a capex, a limit or a probability never carries one.'),
  ('portfolio', 'beginner', 'final', null, 41, 'Risking every row by hand before solving, a candidate''s value for one project differs from the explorer''s risked EMV column. What causes does the method name?', '["Grid rounding, since the column shows EMV after capex is rounded to cells.", "The simulation, since the column reports the mean of the seeded Monte Carlo draws, which never lands exactly on the hand line.", "Correlation, which the explorer applies to each project''s EMV before printing.", "A mistyped input, or a clamp that fired: pos over 1 read as 1, pos under 0 as 0, a negative fail_cost as 0."]'::jsonb, 3, 'The engine keeps no record of the value typed before a clamp; OK-3''s hand line, 0.250000 x 420.0000 - 0.750000 x 85.0000 = 41.2500, matching the engine shows the row was read as typed.'),
  ('portfolio', 'beginner', 'final', null, 42, 'freeProjectZeroLimit and limitBelowEveryProject both return an empty set with an EMV of 0.0000. Which of them left value behind that the exact optimum would have taken?', '["freeProjectZeroLimit, where a project costing 0.0000 and worth 10.0000 needed one cell that a limit of 0.0000 does not hold; below every project nothing fits in money either.", "limitBelowEveryProject, since a limit of 30.0000 could have funded part of A, and the knapsack''s refusal to split a project into fractions is where the value was lost in that case.", "Both of them, since an empty set always means the grid has undershot and a better set of whole projects was squeezed out.", "Neither, since an empty set is the engine refusing a limit it cannot use, and no optimum exists for either input."]'::jsonb, 0, 'The golden optimum for freeProjectZeroLimit is 10.0000 on free, a gap of -10.0000 (finding D2), while the golden optimum for limitBelowEveryProject is the empty set.');
